// ── Shared form validators ──
// Reject spaces/commas/semicolons and require an alphabetic TLD (≥2) so junk like "a@b.co," is caught.
const isEmail = (s: string) => /^[^\s@,;]+@[^\s@,;]+\.[a-zA-Z]{2,}$/.test(s.trim());
// Phone: digits/+/space/-/() only, 7–15 digits (matches intl + KSA numbers)
const isPhone = (s: string) => { const t = s.trim(); const digits = t.replace(/\D/g, ""); return /^[+\d][\d\s()-]*$/.test(t) && digits.length >= 7 && digits.length <= 15; };
// Derive Iqama status automatically from the expiry date: overdue if past, expiring within 30 days, else valid.
const statusFromExpiry = (d: string): "valid" | "expiring" | "overdue" => {
  if (!d) return "valid";
  const exp = new Date(d + "T00:00:00");
  if (isNaN(exp.getTime())) return "valid";
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const days = Math.round((exp.getTime() - today.getTime()) / 86400000);
  return days < 0 ? "overdue" : days <= 30 ? "expiring" : "valid";
};
const isPositiveNumber = (v: string | number) => { const n = typeof v === "number" ? v : parseFloat(String(v).replace(/,/g, "")); return Number.isFinite(n) && n > 0; };
// "1 task" / "2 tasks" — correct singular/plural
const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;

// Shared modal input style + client-edit field list (kept module-level so the Edit modal
// mirrors the Add modal and inputs stay mounted — no nested component = no focus loss)
const MODAL_INPUT = "w-full px-3 py-2 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/40 focus:border-ring/40 transition";
