// ── Clean-path routing (dashboard = "/", others = "/<screen>") ──
const pathForScreen = (s: string) => (s === "dashboard" ? "/" : `/${s}`);
const screenFromPath = (): string => {
  const seg = (typeof window !== "undefined" ? window.location.pathname : "/").replace(/^\/+/, "").split(/[/?#]/)[0];
  return seg || "dashboard";
};

