// Persist state to localStorage (survives reload). Bump the version to reset all persisted data to seed.
const PERSIST_VERSION = "v1";
function usePersistentState<T>(key: string, initial: T): [T, React.Dispatch<React.SetStateAction<T>>] {
  const storageKey = `stimespro:${PERSIST_VERSION}:${key}`;
  const [state, setState] = useState<T>(() => {
    try { const saved = localStorage.getItem(storageKey); return saved !== null ? (JSON.parse(saved) as T) : initial; } catch { return initial; }
  });
  useEffect(() => {
    try { localStorage.setItem(storageKey, JSON.stringify(state)); } catch { /* quota / private mode — ignore */ }
  }, [storageKey, state]);
  return [state, setState];
}

