function Avatar({ name, size = "sm" }: { name: string; size?: "xs" | "sm" | "md" }) {
  const initials = name.split(" ").map(n => n[0]).slice(0, 2).join("").toUpperCase();
  const sizes = { xs: "w-6 h-6 text-[10px]", sm: "w-8 h-8 text-xs", md: "w-9 h-9 text-sm" };
  const colors = ["bg-violet-500","bg-indigo-500","bg-rose-500","bg-emerald-500","bg-amber-500","bg-cyan-500"];
  const idx = name.charCodeAt(0) % colors.length;
  return (
    <div className={`${sizes[size]} ${colors[idx]} rounded-full flex items-center justify-center text-white font-semibold flex-shrink-0`}>
      {initials}
    </div>
  );
}

