const CAL_EVENTS = [
  { id: "e1", title: "Iqama Renewal — Ahmed", date: "2025-01-24", type: "renewal", client: "Global Tech LLC", color: "bg-purple-100 text-purple-700 border-purple-300" },
  { id: "e2", title: "CR Deadline — TechVault", date: "2025-01-28", type: "deadline", client: "TechVault Arabia", color: "bg-red-100 text-red-700 border-red-300" },
  { id: "e3", title: "Passport Collection", date: "2025-01-29", type: "appointment", client: "SkyBridge Corp", color: "bg-blue-100 text-blue-700 border-blue-300" },
  { id: "e4", title: "GOSI Renewal Batch", date: "2025-01-30", type: "renewal", client: "TechVault Arabia", color: "bg-purple-100 text-purple-700 border-purple-300" },
  { id: "e5", title: "Work Visa Expiry — Kim Lee", date: "2025-01-31", type: "deadline", client: "TechVault Arabia", color: "bg-red-100 text-red-700 border-red-300" },
  { id: "e6", title: "Municipal License Deadline", date: "2025-01-31", type: "deadline", client: "Meridian Services", color: "bg-red-100 text-red-700 border-red-300" },
  { id: "e7", title: "CR Amendment Filing", date: "2025-02-03", type: "appointment", client: "SkyBridge Corp", color: "bg-blue-100 text-blue-700 border-blue-300" },
  { id: "e8", title: "Batch Iqama — AlFuturo", date: "2025-02-05", type: "renewal", client: "AlFuturo Holdings", color: "bg-purple-100 text-purple-700 border-purple-300" },
  { id: "e9", title: "GOSI Filing Deadline", date: "2025-02-10", type: "deadline", client: "TechVault Arabia", color: "bg-red-100 text-red-700 border-red-300" },
  { id: "e10", title: "Work Permit Renewal", date: "2025-02-15", type: "renewal", client: "AlFuturo Holdings", color: "bg-purple-100 text-purple-700 border-purple-300" },
];

function CalendarScreen({ clientId, complianceDocs, tasks, invoices, clients = [] }: {
  clientId: string; complianceDocs: ComplianceDoc[]; tasks: Task[]; invoices: Invoice[]; clients?: Client[];
}) {
  const { clientName, inScope } = clientScope(clientId, clients);
  const [view, setView] = useState<"month" | "week" | "day">("month");
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [curYear, setCurYear] = useState(() => new Date().getFullYear());
  const [curMonth, setCurMonth] = useState(() => new Date().getMonth()); // 0-indexed

  // Parse various date formats to ISO yyyy-mm-dd
  const toISO = (s: string) => {
    const d = new Date(s);
    if (isNaN(d.getTime())) return "";
    return d.toISOString().slice(0, 10);
  };

  // Derive events from shared data
  const derivedEvents = [
    ...complianceDocs.map(d => ({
      id: `cal-c-${d.id}`, title: `${d.docType} — ${d.person}`,
      date: toISO(d.expiryDate), type: "renewal" as const,
      client: d.client, color: "bg-purple-100 text-purple-700 border-purple-300",
    })).filter(e => e.date),
    ...tasks.map(t => ({
      id: `cal-t-${t.id}`, title: t.title,
      date: toISO(t.dueDate), type: "deadline" as const,
      client: t.client, color: "bg-red-100 text-red-700 border-red-300",
    })).filter(e => e.date),
    ...invoices.filter(i => i.status !== "paid").map(i => ({
      id: `cal-i-${i.id}`, title: `Invoice ${i.number} due`,
      date: toISO(i.dueDate), type: "appointment" as const,
      client: i.client, color: "bg-blue-100 text-blue-700 border-blue-300",
    })).filter(e => e.date),
    ...CAL_EVENTS,
  ];

  const visibleEvents = derivedEvents.filter(e => inScope(e.client));

  const daysInMonth = new Date(curYear, curMonth + 1, 0).getDate();
  const startDay = new Date(curYear, curMonth, 1).getDay();

  const monthKey = `${curYear}-${String(curMonth + 1).padStart(2, "0")}`;
  const eventsOnDay = (day: number) => {
    const dateStr = `${monthKey}-${String(day).padStart(2, "0")}`;
    return visibleEvents.filter(e => e.date === dateStr);
  };

  const selectedEvents = selectedDate ? visibleEvents.filter(e => e.date === selectedDate) : [];
  const todayStr = new Date().toISOString().slice(0, 10);
  const monthLabel = new Date(curYear, curMonth).toLocaleDateString("en-US", { month: "long", year: "numeric" });

  const prevMonth = () => { if (curMonth === 0) { setCurMonth(11); setCurYear(y => y-1); } else setCurMonth(m => m-1); };
  const nextMonth = () => { if (curMonth === 11) { setCurMonth(0); setCurYear(y => y+1); } else setCurMonth(m => m+1); };

  const legendItems = [
    { label: "Renewal", color: "bg-purple-400" },
    { label: "Deadline", color: "bg-red-400" },
    { label: "Appointment", color: "bg-blue-400" },
  ];

  return (
    <div>
      <PageHeader
        title="Calendar"
        subtitle="Renewals, deadlines & appointments"
        actions={
          <div className="flex items-center gap-2">
            <div className="flex items-center bg-muted rounded-lg p-1">
              {(["month","week","day"] as const).map(v => (
                <button key={v} onClick={() => setView(v)}
                  className={`px-3 py-1 text-xs font-medium rounded-md capitalize transition-colors ${view === v ? "bg-card text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"}`}>
                  {v}
                </button>
              ))}
            </div>
            <Btn variant="secondary" size="sm" onClick={prevMonth}><ChevronLeft className="w-3.5 h-3.5" /></Btn>
            <span className="text-sm font-medium text-foreground w-36 text-center">{monthLabel}</span>
            <Btn variant="secondary" size="sm" onClick={nextMonth}><ChevronRight className="w-3.5 h-3.5" /></Btn>
          </div>
        }
      />

      <div className="flex gap-5">
        <div className="flex-1 bg-card rounded-xl border border-border overflow-hidden">
          {/* Weekday headers */}
          <div className="grid grid-cols-7 border-b border-border">
            {["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(d => (
              <div key={d} className="py-3 text-center text-xs font-semibold text-muted-foreground">{d}</div>
            ))}
          </div>
          {/* Days grid */}
          <div className="grid grid-cols-7">
            {/* Empty cells before month start */}
            {Array.from({ length: startDay }, (_, i) => (
              <div key={`pre-${i}`} className="min-h-[90px] border-b border-r border-border/40 bg-muted/20" />
            ))}
            {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(day => {
              const dateStr = `${monthKey}-${String(day).padStart(2, "0")}`;
              const dayEvents = eventsOnDay(day);
              const isSelected = selectedDate === dateStr;
              const isToday = dateStr === todayStr;
              return (
                <div
                  key={day}
                  onClick={() => setSelectedDate(isSelected ? null : dateStr)}
                  className={`min-h-[90px] border-b border-r border-border/40 p-1.5 cursor-pointer transition-colors ${isSelected ? "bg-accent/60" : "hover:bg-muted/30"}`}
                >
                  <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-medium mb-1 ${isToday ? "bg-primary text-white" : "text-foreground"}`}>
                    {day}
                  </div>
                  <div className="space-y-0.5">
                    {dayEvents.slice(0, 2).map(ev => (
                      <div key={ev.id} className={`text-[10px] px-1.5 py-0.5 rounded border truncate font-medium ${ev.color}`}>
                        {ev.title}
                      </div>
                    ))}
                    {dayEvents.length > 2 && (
                      <div className="text-[10px] text-muted-foreground px-1">+{dayEvents.length - 2} more</div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Side panel */}
        <div className="w-60 flex-shrink-0 space-y-4">
          {/* Legend */}
          <div className="bg-card rounded-xl border border-border p-4">
            <h3 className="text-xs font-semibold text-foreground mb-3">Legend</h3>
            <div className="space-y-2">
              {legendItems.map(l => (
                <div key={l.label} className="flex items-center gap-2">
                  <span className={`w-2.5 h-2.5 rounded-sm ${l.color}`} />
                  <span className="text-xs text-muted-foreground">{l.label}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Selected day events */}
          {selectedDate && (
            <div className="bg-card rounded-xl border border-border p-4">
              <h3 className="text-xs font-semibold text-foreground mb-3">
                {new Date(selectedDate).toLocaleDateString("en-GB", { day: "numeric", month: "short" })}
              </h3>
              {selectedEvents.length === 0
                ? <p className="text-xs text-muted-foreground">No events</p>
                : <div className="space-y-2">
                    {selectedEvents.map(ev => (
                      <div key={ev.id} className={`p-2.5 rounded-lg border ${ev.color}`}>
                        <p className="text-xs font-semibold">{ev.title}</p>
                        <p className="text-[10px] mt-0.5 opacity-70">{ev.client}</p>
                        <span className="text-[9px] uppercase tracking-wider font-bold opacity-60 mt-1 block">{ev.type}</span>
                      </div>
                    ))}
                  </div>
              }
            </div>
          )}

          {/* Upcoming events */}
          <div className="bg-card rounded-xl border border-border p-4">
            <h3 className="text-xs font-semibold text-foreground mb-3">Upcoming</h3>
            <div className="space-y-2.5">
              {visibleEvents.slice(0, 5).map(ev => (
                <div key={ev.id} className="flex gap-2.5">
                  <div className={`w-1 rounded-full flex-shrink-0 ${ev.type === "renewal" ? "bg-purple-400" : ev.type === "deadline" ? "bg-red-400" : "bg-blue-400"}`} />
                  <div>
                    <p className="text-xs font-medium text-foreground">{ev.title}</p>
                    <p className="text-[10px] text-muted-foreground">{ev.date.slice(5).replace("-", "/")}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// APPROVALS SCREEN
// ─────────────────────────────────────────────────────────────
interface ApprovalItem {
  id: string; title: string; client: string; requestedBy: string;
  type: "iqama_renewal" | "visa_application" | "cr_amendment" | "exit_reentry" | "work_permit";
  priority: Priority; requestedAt: string; daysWaiting: number;
  status: "pending" | "approved" | "rejected" | "escalated";
  amount?: number; notes?: string;
  typeLabel?: string;   // display label for non-PRO approval sources
  _endpoint?: string;   // API path to persist status changes (real approvals)
  _workflow?: boolean;  // this is a BPM workflow approval-node step (id = WorkflowTask id) → persist via /complete
}

const APPROVAL_DATA: ApprovalItem[] = [
  { id: "ap1", title: "Iqama Renewal — Ahmed Al-Rashid", client: "Global Tech LLC", requestedBy: "Khalid Al-Mutairi", type: "iqama_renewal", priority: "high", requestedAt: "Jan 21, 2025", daysWaiting: 2, status: "pending", amount: 1500 },
  { id: "ap2", title: "Work Visa — Li Wei (new hire)", client: "TechVault Arabia", requestedBy: "Omar Abdullah", type: "visa_application", priority: "critical", requestedAt: "Jan 20, 2025", daysWaiting: 3, status: "pending", amount: 3200 },
  { id: "ap3", title: "CR Amendment — address change", client: "SkyBridge Corp", requestedBy: "Fatima Al-Zahra", type: "cr_amendment", priority: "medium", requestedAt: "Jan 22, 2025", daysWaiting: 1, status: "pending", amount: 800 },
  { id: "ap4", title: "Exit Re-entry — Hassan Omar", client: "AlFuturo Holdings", requestedBy: "Khalid Al-Mutairi", type: "exit_reentry", priority: "high", requestedAt: "Jan 19, 2025", daysWaiting: 4, status: "escalated", amount: 450 },
  { id: "ap5", title: "Work Permit — Maria Santos extension", client: "SkyBridge Corp", requestedBy: "Omar Abdullah", type: "work_permit", priority: "medium", requestedAt: "Jan 18, 2025", daysWaiting: 5, status: "pending", amount: 2100 },
  { id: "ap6", title: "Iqama Renewal — Roberto Alvarez", client: "AlFuturo Holdings", requestedBy: "Fatima Al-Zahra", type: "iqama_renewal", priority: "low", requestedAt: "Jan 17, 2025", daysWaiting: 6, status: "approved", amount: 1500, notes: "Approved after document verification" },
];

function ApprovalScreen({ clientId, clients = [], embedded }: { clientId: string; clients?: Client[]; embedded?: boolean }) {
  const { inScope } = clientScope(clientId, clients);
  const [items, setItems] = useState<ApprovalItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [apprSearch, setApprSearch] = useState("");
  const [apprPage, setApprPage] = useState(0);
  useEffect(() => { setApprPage(0); }, [statusFilter, apprSearch]);
  const [noteId, setNoteId] = useState<string | null>(null);
  const [noteText, setNoteText] = useState("");

  // Real approvals = client service requests + package upgrade requests from the DB
  useEffect(() => {
    (async () => {
      try {
        const [srv, ups, mywork] = await Promise.all([
          api.get("/api/service-requests").catch(() => []),
          api.get("/api/upgrade-requests").catch(() => []),
          api.get("/api/workflow/my-work").catch(() => []),
        ]);
        const norm = (s: string): ApprovalItem["status"] =>
          s === "open" ? "pending" : (["pending", "approved", "rejected", "escalated"].includes(s) ? s as ApprovalItem["status"] : "pending");
        const srvItems: ApprovalItem[] = (Array.isArray(srv) ? srv : []).map((r: any) => ({
          id: r.id, title: r.type || (r.message ? String(r.message).slice(0, 60) : "Service request"),
          client: r.clientName || "—", requestedBy: "Client portal", type: "cr_amendment",
          typeLabel: "Service Request", priority: "medium", requestedAt: r.date || "", daysWaiting: 0,
          status: norm(r.status), notes: r.message || undefined, _endpoint: "/api/service-requests",
        }));
        const upItems: ApprovalItem[] = (Array.isArray(ups) ? ups : []).map((r: any) => ({
          id: r.id, title: `Package upgrade → ${packageById(r.toPackageId)?.name ?? r.toPackageId ?? "—"}`,
          client: r.clientName || "—", requestedBy: "Client", type: "cr_amendment",
          typeLabel: "Package Upgrade", priority: "medium", requestedAt: r.date || "", daysWaiting: 0,
          status: norm(r.status), notes: r.note || undefined, _endpoint: "/api/upgrade-requests",
        }));
        // Workflow approval-node steps waiting on a human sign-off → surface in the same queue.
        const wfItems: ApprovalItem[] = (Array.isArray(mywork) ? mywork : [])
          .filter((t: any) => t.nodeType === "approval" && t.status === "active")
          .map((t: any) => ({
            id: t.id, title: t.title || "Approval step",
            client: t.instance?.clientName || t.instance?.title || "—",
            requestedBy: t.assigneeRole ? `Workflow · ${t.assigneeRole}` : "Workflow",
            type: "cr_amendment", typeLabel: "Workflow Approval",
            priority: (t.priority as Priority) || "medium", requestedAt: t.createdAt || "",
            daysWaiting: 0, status: "pending", _workflow: true,
          }));
        setItems([...wfItems, ...upItems, ...srvItems]);
      } catch { /* keep empty */ } finally { setLoading(false); }
    })();
  }, []);

  const filtered = items.filter(i => {
    const q = apprSearch.trim().toLowerCase();
    const matchQ = !q || [i.title, i.client, i.requestedBy, i.typeLabel].some(v => (v || "").toLowerCase().includes(q));
    return (statusFilter === "all" || i.status === statusFilter) && inScope(i.client) && matchQ;
  });

  const persist = (id: string, status: string) => {
    const it = items.find(i => i.id === id);
    if (it?._workflow) {
      // BPM approval step — route the outcome through the engine so the run advances.
      if (status === "approved") api.post(`/api/workflow/tasks/${id}/complete`, { outcome: "approve" }).catch(() => {});
      else if (status === "rejected") api.post(`/api/workflow/tasks/${id}/complete`, { outcome: "reject" }).catch(() => {});
      return; // "escalated" has no workflow equivalent (Escalate is hidden for these)
    }
    if (it?._endpoint) api.put(`${it._endpoint}/${id}`, { status }).catch(() => {});
  };
  const approve = (id: string) => {
    persist(id, "approved");
    setItems(prev => prev.map(i => i.id === id ? { ...i, status: "approved" as const, notes: noteText || i.notes } : i));
    setNoteId(null); setNoteText("");
    toast.success("Request approved");
  };
  const reject = (id: string) => {
    if (!noteText) { toast.error("Please provide a rejection reason"); return; }
    persist(id, "rejected");
    setItems(prev => prev.map(i => i.id === id ? { ...i, status: "rejected" as const, notes: noteText } : i));
    setNoteId(null); setNoteText("");
    toast.success("Request rejected");
  };
  const escalate = (id: string) => {
    persist(id, "escalated");
    setItems(prev => prev.map(i => i.id === id ? { ...i, status: "escalated" as const } : i));
    toast.info("Escalated to Super Admin");
  };

  const typeLabels: Record<ApprovalItem["type"], string> = {
    iqama_renewal: "Iqama Renewal", visa_application: "Visa Application",
    cr_amendment: "CR Amendment", exit_reentry: "Exit/Re-entry", work_permit: "Work Permit",
  };
  const statusCls: Record<ApprovalItem["status"], string> = {
    pending: "bg-amber-50 text-amber-700 ring-amber-600/20",
    approved: "bg-green-50 text-green-700 ring-green-600/20",
    rejected: "bg-red-50 text-red-700 ring-red-600/20",
    escalated: "bg-purple-50 text-purple-700 ring-purple-600/20",
  };

  const counts = { all: items.length, pending: items.filter(i => i.status === "pending").length, escalated: items.filter(i => i.status === "escalated").length, approved: items.filter(i => i.status === "approved").length };

  if (loading) return <PageLoader message="Loading approvals…" />;
  return (
    <div>
      <PageHeader title="Approvals" subtitle="Pending sign-offs and escalations" />
      <StatStrip stats={[
        { label: "Total requests", value: counts.all, Icon: ThumbsUp, grad: ["#3b82f6", "#2563eb"] },
        { label: "Pending", value: counts.pending, Icon: Clock, grad: ["#a855f7", "#7105ef"] },
        { label: "Escalated", value: counts.escalated, Icon: Flag, grad: ["#fbbf24", "#d97706"] },
        { label: "Approved", value: counts.approved, Icon: CheckCircle2, grad: ["#34d399", "#059669"] },
      ]} />


      <TableToolbar search={apprSearch} onSearch={setApprSearch} searchPlaceholder="Search request, client or requester…"
        filters={["All", "Pending", "Escalated", "Approved", "Rejected"]} onFilter={l => setStatusFilter(l.toLowerCase())}
        activeFilter={statusFilter === "all" ? "All" : statusFilter.charAt(0).toUpperCase() + statusFilter.slice(1)} />
      <div className="bg-card rounded-xl border border-border overflow-hidden flex flex-col" style={{ height: TABLE_MIN_H }}>
        <div className="overflow-x-auto flex-1" style={{ overflowY: "auto" }}>
          <table className="w-full">
            <thead><tr className="border-b border-border bg-muted/30">{["Request", "Requested by", "Priority", "Waiting", "Status", "_a"].map(h => <th key={h} className="text-left py-3 px-4 text-xs font-semibold text-muted-foreground">{h.startsWith("_") ? "Actions" : h}</th>)}</tr></thead>
            <tbody>
              {filtered.length === 0 && <tr><td colSpan={6}><EmptyState icon={CheckCircle2} title="No approvals" message={statusFilter === "all" ? "No client requests are awaiting sign-off." : `No ${statusFilter} requests.`} /></td></tr>}
              {pageSlice(filtered, apprPage, LIST_PAGE_SIZE).slice.map((item, i0) => { const i = pageSlice(filtered, apprPage, LIST_PAGE_SIZE).start + i0; return (
                <Fragment key={item.id}>
                <tr className="border-b border-border/60 hover:bg-muted/40 transition-colors">
                  <td className="py-3 px-4">
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-primary/10 text-primary flex items-center justify-center text-[10px] font-bold flex-shrink-0" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>{String(i + 1).padStart(3, "0")}</span>
                      <div className="min-w-0">
                        <div className="flex items-center gap-2"><span className="text-[10px] bg-muted text-muted-foreground px-1.5 py-0.5 rounded-full">{item.typeLabel ?? typeLabels[item.type]}</span>{item.status === "escalated" && <Flag className="w-3 h-3 text-purple-600" />}</div>
                        <p className="text-sm font-medium text-foreground max-w-[240px] truncate mt-0.5">{item.title}</p>
                        <p className="text-[10px] text-muted-foreground truncate max-w-[240px]">{item.client}{item.amount ? ` · SAR ${item.amount.toLocaleString()}` : ""}</p>
                      </div>
                    </div>
                  </td>
                  <td className="py-3 px-4"><div className="flex items-center gap-2"><Avatar name={item.requestedBy} size="xs" /><span className="text-xs text-foreground hidden sm:block truncate max-w-[120px]">{item.requestedBy}</span></div></td>
                  <td className="py-3 px-4"><PriorityBadge priority={item.priority} /></td>
                  <td className="py-3 px-4"><span className="text-xs text-muted-foreground">{item.daysWaiting}d</span></td>
                  <td className="py-3 px-4"><span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ring-1 ring-inset ${statusCls[item.status]}`}>{item.status}</span></td>
                  <td className="py-3 px-4">
                    {item.status === "pending" ? (
                      <div className="flex items-center gap-1.5">
                        <Btn variant="primary" size="xs" onClick={() => setNoteId(noteId === item.id ? null : item.id)}><ThumbsUp className="w-3 h-3" />Review</Btn>
                        {!item._workflow && <Btn variant="ghost" size="xs" onClick={() => escalate(item.id)}><Flag className="w-3 h-3" />Escalate</Btn>}
                      </div>
                    ) : <span className="text-xs text-muted-foreground">—</span>}
                  </td>
                </tr>
                {noteId === item.id && (
                  <tr className="bg-muted/20 border-b border-border/60"><td colSpan={6} className="px-6 py-4">
                    <p className="text-xs font-semibold text-foreground mb-2">Review — {item.title}</p>
                    {item.notes && <p className="text-xs text-muted-foreground italic mb-2">Client note: "{item.notes}"</p>}
                    <textarea value={noteText} onChange={e => setNoteText(e.target.value)} placeholder="Add a note (required for rejection)…" className="w-full max-w-md text-xs border border-border rounded-lg px-3 py-2 bg-card focus:outline-none focus:ring-2 focus:ring-ring/50 resize-none h-16" />
                    <div className="flex gap-1.5 mt-2">
                      <Btn variant="primary" size="sm" onClick={() => approve(item.id)}><ThumbsUp className="w-3.5 h-3.5" />Approve</Btn>
                      <Btn variant="danger" size="sm" onClick={() => reject(item.id)}><ThumbsDown className="w-3.5 h-3.5" />Reject</Btn>
                      <Btn variant="ghost" size="sm" onClick={() => { setNoteId(null); setNoteText(""); }}>Cancel</Btn>
                    </div>
                  </td></tr>
                )}
                </Fragment>
              ); })}
            </tbody>
          </table>
        </div>
        <Pagination page={apprPage} setPage={setApprPage} total={filtered.length} perPage={LIST_PAGE_SIZE} />
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// SLA MONITOR SCREEN
// ─────────────────────────────────────────────────────────────
interface SLAItem {
  id: string; title: string; client: string; assignee: string;
  docType: string; dueDate: string; daysRemaining: number;
  slaStatus: "on_track" | "at_risk" | "breached";
  slaTarget: number; progress: number;
}

const SLA_DATA: SLAItem[] = [
  { id: "s1", title: "Iqama Renewal — Kim Lee", client: "TechVault Arabia", assignee: "Khalid", docType: "Iqama", dueDate: "Jan 25, 2025", daysRemaining: -2, slaStatus: "breached", slaTarget: 7, progress: 110 },
  { id: "s2", title: "CR Submission — Global Tech", client: "Global Tech LLC", assignee: "Omar", docType: "Commercial Register", dueDate: "Jan 26, 2025", daysRemaining: 1, slaStatus: "at_risk", slaTarget: 5, progress: 90 },
  { id: "s3", title: "Visa Processing — Maria Santos", client: "SkyBridge Corp", assignee: "Fatima", docType: "Work Visa", dueDate: "Jan 28, 2025", daysRemaining: 3, slaStatus: "at_risk", slaTarget: 10, progress: 72 },
  { id: "s4", title: "Municipal License — Meridian", client: "Meridian Services", assignee: "Khalid", docType: "Municipal License", dueDate: "Jan 31, 2025", daysRemaining: 6, slaStatus: "on_track", slaTarget: 14, progress: 55 },
  { id: "s5", title: "Work Permit — Roberto Alvarez", client: "AlFuturo Holdings", assignee: "Omar", docType: "Work Permit", dueDate: "Feb 5, 2025", daysRemaining: 11, slaStatus: "on_track", slaTarget: 21, progress: 38 },
  { id: "s6", title: "GOSI Registration — TechVault", client: "TechVault Arabia", assignee: "Fatima", docType: "GOSI", dueDate: "Feb 10, 2025", daysRemaining: 16, slaStatus: "on_track", slaTarget: 21, progress: 20 },
  { id: "s7", title: "Exit Re-entry — Hassan", client: "AlFuturo Holdings", assignee: "Khalid", docType: "Exit/Re-entry", dueDate: "Jan 27, 2025", daysRemaining: 2, slaStatus: "at_risk", slaTarget: 5, progress: 85 },
];

function SLAScreen({ clientId, complianceDocs, clients = [], embedded }: { clientId: string; complianceDocs: ComplianceDoc[]; clients?: Client[]; embedded?: boolean }) {
  const { inScope } = clientScope(clientId, clients);
  const [sortBy] = useState<"days" | "status">("days");
  const [slaSearch, setSlaSearch] = useState("");
  const [slaFilterLabel, setSlaFilterLabel] = useState("All");
  const [slaPage, setSlaPage] = useState(0);
  useEffect(() => { setSlaPage(0); }, [slaSearch, slaFilterLabel]);
  const SLA_FILTER: Record<string, string> = { "On track": "on_track", "At risk": "at_risk", "Breached": "breached" };
  useEffect(() => { setFilterStatus(slaFilterLabel === "All" ? "all" : SLA_FILTER[slaFilterLabel]); /* eslint-disable-next-line */ }, [slaFilterLabel]);
  const [filterStatus, setFilterStatus] = useState<string>("all");
  const [escalated, setEscalated] = useState<string[]>([]);

  // Active workflow steps with an SLA target — elapsed-vs-slaHours drives breach/at-risk.
  const [wfTasks, setWfTasks] = useState<any[]>([]);
  useEffect(() => { (async () => { try { const s = await api.get("/api/workflow/my-work"); setWfTasks(Array.isArray(s) ? s : []); } catch { /* offline */ } })(); }, []);

  // SLA cases = live document renewals + SLA-bound workflow steps; deadline drives on-track / at-risk / breached
  const docBase: SLAItem[] = complianceDocs
    .filter(d => inScope(d.client))
    .map(d => {
      const slaStatus: SLAItem["slaStatus"] = d.daysLeft < 0 ? "breached" : d.daysLeft <= 7 ? "at_risk" : "on_track";
      const slaTarget = 30;
      const progress = Math.min(110, Math.max(0, Math.round(((slaTarget - d.daysLeft) / slaTarget) * 100)));
      return { id: d.id, title: `${d.docType} — ${d.person}`, client: d.client, assignee: "—", docType: d.docType, dueDate: d.expiryDate, daysRemaining: d.daysLeft, slaStatus, slaTarget, progress };
    });
  const wfBase: SLAItem[] = wfTasks
    .filter(t => t.slaHours && t.createdAt && inScope(t.instance?.clientName))
    .map(t => {
      const elapsedH = (Date.now() - new Date(t.createdAt).getTime()) / 3600000;
      const remH = t.slaHours - elapsedH;
      const slaStatus: SLAItem["slaStatus"] = remH < 0 ? "breached" : remH <= t.slaHours * 0.25 ? "at_risk" : "on_track";
      const progress = Math.min(110, Math.max(0, Math.round((elapsedH / t.slaHours) * 100)));
      return { id: `wf-${t.id}`, title: `${t.title} · workflow`, client: t.instance?.clientName || "—", assignee: t.assigneeRole || "—", docType: "Workflow", dueDate: "", daysRemaining: Math.round(remH / 24), slaStatus, slaTarget: Math.max(1, Math.round(t.slaHours / 24)), progress };
    });
  const base: SLAItem[] = [...wfBase, ...docBase];
  const sorted = [...base]
    .filter(i => filterStatus === "all" || i.slaStatus === filterStatus)
    .filter(i => { const q = slaSearch.trim().toLowerCase(); return !q || [i.title, i.client, i.assignee, i.docType].some(v => (v || "").toLowerCase().includes(q)); })
    .sort((a, b) => sortBy === "days" ? a.daysRemaining - b.daysRemaining : 0);

  const counts = {
    breached: base.filter(i => i.slaStatus === "breached").length,
    at_risk: base.filter(i => i.slaStatus === "at_risk").length,
    on_track: base.filter(i => i.slaStatus === "on_track").length,
  };

  const slaColors: Record<SLAItem["slaStatus"], { bar: string; badge: string; text: string }> = {
    breached: { bar: "bg-red-500", badge: "bg-red-50 text-red-700 ring-red-600/20", text: "text-red-600" },
    at_risk: { bar: "bg-amber-400", badge: "bg-amber-50 text-amber-700 ring-amber-600/20", text: "text-amber-600" },
    on_track: { bar: "bg-emerald-500", badge: "bg-green-50 text-green-700 ring-green-600/20", text: "text-green-600" },
  };

  return (
    <div>
      <PageHeader title="SLA Monitor" subtitle="Service level agreement tracking across all active cases" />
      <StatStrip stats={[
        { label: "Total cases", value: base.length, Icon: Timer, grad: ["#3b82f6", "#2563eb"] },
        { label: "On track", value: counts.on_track, Icon: CheckCircle2, grad: ["#34d399", "#059669"] },
        { label: "At risk", value: counts.at_risk, Icon: Clock, grad: ["#fbbf24", "#d97706"] },
        { label: "Breached", value: counts.breached, Icon: AlertTriangle, grad: ["#fb7185", "#e11d48"] },
      ]} />


      <TableToolbar search={slaSearch} onSearch={setSlaSearch} searchPlaceholder="Search case, client or assignee…"
        filters={["All", "On track", "At risk", "Breached"]} onFilter={setSlaFilterLabel} activeFilter={slaFilterLabel} />

      <div className="bg-card rounded-xl border border-border overflow-hidden flex flex-col" style={{ height: TABLE_MIN_H }}>
        <div className="overflow-x-auto flex-1" style={{ overflowY: "auto" }}>
        <table className="w-full">
          <thead>
            <tr className="border-b border-border bg-muted/30">
              {["Task","Client","Assignee","Due Date","Days Remaining","SLA Progress","Status","_sla_act"].map(h => (
                <th key={h} className="text-left py-3 px-4 text-xs font-semibold text-muted-foreground">
                  {h.startsWith("_") ? "" : h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {pageSlice(sorted, slaPage, LIST_PAGE_SIZE).slice.map(item => {
              const cfg = slaColors[item.slaStatus];
              return (
                <tr key={item.id} className="border-b border-border/60 hover:bg-muted/30 transition-colors">
                  <td className="py-3 px-4">
                    <p className="text-sm font-medium text-foreground">{item.title}</p>
                    <p className="text-xs text-muted-foreground">{item.docType}</p>
                  </td>
                  <td className="py-3 px-4 text-sm text-foreground">{item.client}</td>
                  <td className="py-3 px-4"><Avatar name={item.assignee} size="xs" /></td>
                  <td className="py-3 px-4 text-sm text-muted-foreground">{item.dueDate}</td>
                  <td className="py-3 px-4">
                    <span className={`text-sm font-bold ${cfg.text}`}>
                      {item.daysRemaining < 0 ? `${Math.abs(item.daysRemaining)}d overdue` : `${item.daysRemaining}d left`}
                    </span>
                  </td>
                  <td className="py-3 px-4 w-36">
                    <div className="w-full bg-muted rounded-full h-1.5">
                      <div className={`${cfg.bar} h-1.5 rounded-full transition-all`} style={{ width: `${Math.min(item.progress, 100)}%` }} />
                    </div>
                    <p className="text-[10px] text-muted-foreground mt-0.5">{item.progress}% of SLA target</p>
                  </td>
                  <td className="py-3 px-4">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ring-1 ring-inset ${cfg.badge}`}>
                      {item.slaStatus.replace("_", " ")}
                    </span>
                  </td>
                  <td className="py-3 px-4">
                    {item.slaStatus !== "on_track" && (
                      escalated.includes(item.id)
                        ? <span className="inline-flex items-center gap-1 text-xs font-medium text-red-600"><Flag className="w-3 h-3" />Escalated</span>
                        : <Btn variant="ghost" size="xs" onClick={() => { setEscalated(prev => [...prev, item.id]); toast.info(`Escalated: ${item.title}`); }}>
                            <Flag className="w-3 h-3" />Escalate
                          </Btn>
                    )}
                  </td>
                </tr>
              );
            })}
            {sorted.length === 0 && (
              <tr><td colSpan={8}><EmptyState icon={ShieldCheck} title="No SLA cases" message="Document renewals with deadlines will appear here." /></td></tr>
            )}
          </tbody>
        </table>
        </div>
        <Pagination page={slaPage} setPage={setSlaPage} total={sorted.length} perPage={LIST_PAGE_SIZE} />
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// AUDIT TRAIL SCREEN
// ─────────────────────────────────────────────────────────────
interface AuditEntry { id: string; action: string; actorId?: string; actorEmail?: string; target?: string; detail?: string; ip?: string; at: string; }

function AuditScreen() {
  const [search, setSearch] = useState("");
  const [rows, setRows] = useState<AuditEntry[]>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    (async () => { try { const d = await api.get("/api/audit"); if (Array.isArray(d)) setRows(d); } catch { /* keep empty */ } finally { setLoading(false); } })();
  }, []);

  const filtered = rows.filter(a =>
    a.action.toLowerCase().includes(search.toLowerCase()) ||
    (a.actorEmail ?? "").toLowerCase().includes(search.toLowerCase()) ||
    (a.target ?? "").toLowerCase().includes(search.toLowerCase())
  );

  const badge = (action: string) => {
    if (action.includes("fail") || action.includes("locked")) return "bg-red-50 text-red-700 ring-red-600/20";
    if (action.includes("success") || action === "login") return "bg-green-50 text-green-700 ring-green-600/20";
    if (action.includes("reveal")) return "bg-purple-50 text-purple-700 ring-purple-600/20";
    if (action.includes("password") || action.includes("reset")) return "bg-amber-50 text-amber-700 ring-amber-600/20";
    return "bg-blue-50 text-blue-700 ring-blue-600/20";
  };
  const fmt = (iso: string) => { try { return new Date(iso).toLocaleString("en-GB", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }); } catch { return iso; } };

  if (loading) return <PageLoader message="Loading audit trail…" />;
  return (
    <div>
      <PageHeader
        title="Audit Trail"
        subtitle="Immutable log of security & account events — who did what, when, and from where"
        actions={<div className="flex gap-2">
          <Btn variant="secondary" size="sm" onClick={() => { tableReportPDF("Audit Trail", ["Action","Actor","Target","Detail","IP","Time"], filtered.map(a => [a.action, a.actorEmail ?? a.actorId ?? "", a.target ?? "", a.detail ?? "", a.ip ?? "", a.at]), "audit-log.pdf"); toast.success("audit-log.pdf downloaded"); }}><FileText className="w-3.5 h-3.5" />Export PDF</Btn>
          <Btn variant="ghost" size="sm" onClick={() => exportCSV(filtered.map(a => ({ Action: a.action, Actor: a.actorEmail ?? a.actorId ?? "", Target: a.target ?? "", Detail: a.detail ?? "", IP: a.ip ?? "", Time: a.at })), "audit-log.csv")}><Download className="w-3.5 h-3.5" />Export CSV</Btn>
        </div>}
      />

      <div className="flex items-center gap-3 mb-4">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
          <input type="text" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search action, user or target…"
            className="w-full pl-9 pr-3 py-2 text-sm bg-card border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/50" />
        </div>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden flex flex-col" style={{ height: TABLE_MIN_H }}>
        <div className="overflow-x-auto flex-1" style={{ overflowY: "auto" }}>
        <table className="w-full">
          <thead>
            <tr className="border-b border-border bg-muted/30">
              {["Action","Actor","Target","Detail","IP Address","Timestamp"].map(h => (
                <th key={h} className="text-left py-3 px-4 text-xs font-semibold text-muted-foreground">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map(entry => (
              <tr key={entry.id} className="border-b border-border/60 hover:bg-muted/30 transition-colors">
                <td className="py-3 px-4"><span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ring-1 ring-inset ${badge(entry.action)}`}>{entry.action}</span></td>
                <td className="py-3 px-4"><span className="text-xs text-foreground">{entry.actorEmail ?? entry.actorId ?? "—"}</span></td>
                <td className="py-3 px-4"><span className="text-xs text-foreground">{entry.target ?? "—"}</span></td>
                <td className="py-3 px-4"><span className="text-xs text-muted-foreground">{entry.detail ?? "—"}</span></td>
                <td className="py-3 px-4"><code className="text-xs font-mono text-muted-foreground">{entry.ip ?? "—"}</code></td>
                <td className="py-3 px-4"><span className="text-xs text-muted-foreground whitespace-nowrap">{fmt(entry.at)}</span></td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={6}><EmptyState icon={History} title="No audit events" message="Logins, password changes and credential reveals will appear here." /></td></tr>
            )}
          </tbody>
        </table>
        </div>
      </div>
    </div>
  );
}

