interface ChatMessage { id: string; role: "user" | "assistant"; content: string; ts: string; }

const AI_EXAMPLES = [
  { icon: "🔍", label: "Find expired passports", prompt: "Show me all expired passports across all clients" },
  { icon: "🔄", label: "Create renewal project", prompt: "Create a renewal project for TechVault Arabia — batch Iqama renewals" },
  { icon: "🧾", label: "Generate invoice", prompt: "Generate an invoice for Global Tech LLC for January Iqama renewals" },
  { icon: "📋", label: "Summarize client", prompt: "Summarize the compliance status for AlFuturo Holdings" },
  { icon: "📊", label: "Revenue this quarter", prompt: "What is the total revenue collected this quarter?" },
  { icon: "⚠️", label: "SLA breaches today", prompt: "List all SLA breaches and at-risk items today" },
];

const AI_SUGGESTED = [
  "Send renewal reminders to all clients with expiring docs in 14 days",
  "Archive completed projects older than 90 days",
  "Export compliance report for TechVault Arabia as PDF",
  "Assign unassigned tasks to available PRO officers",
];

const MOCK_RESPONSES: Record<string, string> = {
  "Show me all expired passports across all clients": "I found **2 expired passports** across your active clients:\n\n• **Hassan Yusuf** (TechVault Arabia) — Iqama expired Jan 5, 2025 · 19 days overdue\n• **Kim Lee** (TechVault Arabia) — Work Visa expired Jan 10, 2025 · 14 days overdue\n\nWould you like me to create renewal tasks for both, or send reminders to the client admin?",
  "Create a renewal project for TechVault Arabia — batch Iqama renewals": "I've drafted a **Batch Iqama Renewal** project for TechVault Arabia:\n\n• **15 employees** due for renewal\n• Estimated timeline: **21 days**\n• Estimated fee: **SAR 22,500**\n• Assigned to: **Omar Abdullah**\n\nShall I create this project and notify the client contact Mohammed Al-Otaibi?",
  "Generate an invoice for Global Tech LLC for January Iqama renewals": "I've prepared **Draft Invoice INV-2025-006** for Global Tech LLC:\n\n• Iqama Renewals × 8 — SAR 12,000\n• Government fees — SAR 2,400\n• Service charge (10%) — SAR 1,440\n• **Total: SAR 15,840**\n\nShall I save this as a draft or send it directly to Abdullah Al-Ghamdi?",
  "Summarize the compliance status for AlFuturo Holdings": "**AlFuturo Holdings** — Compliance Summary (Jan 23, 2025)\n\n✅ **Valid:** 84 documents (89 employees)\n⚠️ **Expiring ≤30d:** 8 documents (Iqamas, work permits)\n❌ **Overdue:** 4 documents\n\n**Action needed:** Work Permit for Zhang Wei expires Feb 28. Roberto Alvarez's Iqama is at risk.\n\nOverall compliance score: **76%** — below the 80% target.",
};

const DEFAULT_RESPONSE = "I'm analyzing your request across all active clients and documents. Based on the current data, I can help you take action on this directly or generate a detailed report. Would you like me to proceed?";

function AIAssistantScreen() {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { id: "m0", role: "assistant", content: "Hi! I'm your STIMES AI Assistant. I can help you find information, create projects, generate invoices, and take actions across your ERP. What would you like to do?", ts: "Just now" },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const endRef = useRef<HTMLDivElement>(null);

  const send = (text: string) => {
    if (!text.trim() || loading) return;
    const userMsg: ChatMessage = { id: `m${Date.now()}`, role: "user", content: text, ts: "Just now" };
    setMessages(prev => [...prev, userMsg]);
    setInput("");
    setLoading(true);
    setTimeout(() => {
      const reply = MOCK_RESPONSES[text] || DEFAULT_RESPONSE;
      setMessages(prev => [...prev, { id: `m${Date.now() + 1}`, role: "assistant", content: reply, ts: "Just now" }]);
      setLoading(false);
      setTimeout(() => endRef.current?.scrollIntoView({ behavior: "smooth" }), 50);
    }, 900);
  };

  return (
    <div className="flex gap-5 h-[calc(100vh-140px)]">
      {/* Chat panel */}
      <div className="flex-1 flex flex-col bg-card rounded-xl border border-border overflow-hidden">
        {/* Header */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-border flex-shrink-0">
          <div className="w-9 h-9 rounded-xl bg-primary flex items-center justify-center">
            <Bot className="w-5 h-5 text-white" />
          </div>
          <div>
            <h2 className="text-sm font-semibold text-foreground">STIMES AI Assistant</h2>
            <p className="text-xs text-muted-foreground">Powered by enterprise intelligence · Context: All Clients</p>
          </div>
          <span className="ml-auto flex items-center gap-1.5 text-xs text-emerald-600 font-medium">
            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />Online
          </span>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-4">
          {messages.map(msg => (
            <div key={msg.id} className={`flex gap-3 ${msg.role === "user" ? "flex-row-reverse" : ""}`}>
              {msg.role === "assistant"
                ? <div className="w-8 h-8 rounded-lg bg-primary flex items-center justify-center flex-shrink-0"><Bot className="w-4 h-4 text-white" /></div>
                : <Avatar name="Khalid Al-Mutairi" size="sm" />
              }
              <div className={`max-w-[75%] rounded-xl px-4 py-3 ${msg.role === "assistant" ? "bg-muted text-foreground" : "bg-primary text-white"}`}>
                <p className="text-sm whitespace-pre-line leading-relaxed">{msg.content}</p>
                <p className={`text-[10px] mt-1.5 ${msg.role === "assistant" ? "text-muted-foreground" : "text-white/60"}`}>{msg.ts}</p>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex gap-3">
              <div className="w-8 h-8 rounded-lg bg-primary flex items-center justify-center flex-shrink-0"><Bot className="w-4 h-4 text-white" /></div>
              <div className="bg-muted rounded-xl px-4 py-3 flex items-center gap-1.5">
                {[0,1,2].map(i => <span key={i} className="w-1.5 h-1.5 rounded-full bg-muted-foreground animate-bounce" style={{ animationDelay: `${i * 0.15}s` }} />)}
              </div>
            </div>
          )}
          <div ref={endRef} />
        </div>

        {/* Input */}
        <div className="border-t border-border px-4 py-3 flex-shrink-0">
          <div className="flex gap-2">
            <input
              value={input} onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === "Enter" && !e.shiftKey && (e.preventDefault(), send(input))}
              placeholder="Ask anything — find docs, create tasks, generate reports…"
              className="flex-1 px-4 py-2.5 text-sm bg-muted border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-ring/50 transition"
            />
            <Btn variant="primary" size="md" onClick={() => send(input)} disabled={!input.trim() || loading}>
              <Send className="w-4 h-4" />
            </Btn>
          </div>
        </div>
      </div>

      {/* Sidebar */}
      <div className="w-64 flex-shrink-0 space-y-4 overflow-y-auto">
        {/* Example prompts */}
        <div className="bg-card rounded-xl border border-border p-4">
          <div className="flex items-center gap-2 mb-3">
            <Sparkles className="w-3.5 h-3.5 text-primary" />
            <h3 className="text-xs font-semibold text-foreground">Example Prompts</h3>
          </div>
          <div className="space-y-1.5">
            {AI_EXAMPLES.map(ex => (
              <button key={ex.label} onClick={() => send(ex.prompt)}
                className="w-full text-left px-3 py-2.5 rounded-lg bg-muted hover:bg-accent hover:text-foreground text-muted-foreground transition-colors group">
                <span className="text-sm">{ex.icon}</span>
                <span className="text-xs font-medium ml-2 group-hover:text-foreground">{ex.label}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Suggested actions */}
        <div className="bg-card rounded-xl border border-border p-4">
          <div className="flex items-center gap-2 mb-3">
            <Zap className="w-3.5 h-3.5 text-primary" />
            <h3 className="text-xs font-semibold text-foreground">Suggested Actions</h3>
          </div>
          <div className="space-y-2">
            {AI_SUGGESTED.map((s, i) => (
              <button key={i} onClick={() => toast.info("Action queued: " + s.slice(0, 40) + "…")}
                className="w-full text-left p-2.5 rounded-lg border border-border hover:border-primary/40 hover:bg-accent/40 transition-colors">
                <p className="text-xs text-foreground">{s}</p>
              </button>
            ))}
          </div>
        </div>

        {/* Capabilities */}
        <div className="bg-accent/60 rounded-xl border border-border p-4">
          <h3 className="text-xs font-semibold text-foreground mb-2">Capabilities</h3>
          {["Search & filter records","Create tasks & projects","Generate invoices & reports","Send notifications","Bulk operations","Summarize client status"].map(c => (
            <div key={c} className="flex items-center gap-2 py-1">
              <CheckCircle2 className="w-3 h-3 text-emerald-500 flex-shrink-0" />
              <span className="text-xs text-muted-foreground">{c}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

