const KB_CONTENT: Record<string, string> = {
  kb1: `## Saudi Arabia: Iqama Renewal — Step by Step\n\n### Prerequisites\n- Valid passport (min 6 months remaining)\n- Employer approval via Muqeem\n- GOSI registration current\n- No traffic violations pending\n\n### Process\n1. **Log into Absher Business** → Select employee\n2. Navigate to **Iqama Services → Renew Iqama**\n3. Confirm employer details and salary information\n4. **Pay fees** via SADAD (fees vary by nationality/profession)\n5. Submit via **Muqeem portal** for MOI processing\n6. Iqama typically issued within **7–14 working days**\n\n### Fees (2025)\n- Standard renewal: SAR 650/year\n- Dependent levy: SAR 400/month per dependent\n\n### Common Issues\n- Rejected: Ensure GOSI is up to date before submission\n- Delayed: Check Jawazat status via Absher\n\n### Portals\n- Absher Business: absher.sa\n- Muqeem: muqeem.com.sa\n- Jawazat enquiry: moi.gov.sa`,
};

function KnowledgeBaseScreen() {
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [selectedArticle, setSelectedArticle] = useState<typeof KB_ARTICLES[0] | null>(null);

  const categories = ["All", "Saudi Arabia", "UAE", "Qatar", "Bahrain", "Kuwait", "Oman"];
  const countryFlags: Record<string, string> = { SA: "🇸🇦", AE: "🇦🇪", QA: "🇶🇦", BH: "🇧🇭", KW: "🇰🇼", OM: "🇴🇲" };

  const filtered = KB_ARTICLES.filter(a =>
    (selectedCategory === "All" || a.category === selectedCategory) &&
    (a.title.toLowerCase().includes(search.toLowerCase()) || a.tags.some(t => t.toLowerCase().includes(search.toLowerCase())))
  );

  if (selectedArticle) {
    const content = KB_CONTENT[selectedArticle.id] || `## ${selectedArticle.title}\n\nDetailed SOP content for this procedure. This article covers step-by-step guidance, required documents, fees, timelines, and portal links.\n\n### Steps\n1. Gather required documents\n2. Access the relevant government portal\n3. Submit application with attachments\n4. Pay applicable fees\n5. Track application status\n6. Collect approved documents\n\n### Required Documents\n- Valid passport\n- Employer letter\n- Previous permit (if renewal)\n- Medical fitness certificate (if applicable)\n\n### Timeline\nTypically **7–21 working days** depending on authority.\n\n### Contact\nFor urgent cases contact the helpdesk on the government portal.`;
    return (
      <div>
        <button onClick={() => setSelectedArticle(null)} className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground mb-4 transition-colors">
          <ChevronLeft className="w-4 h-4" />Back to Knowledge Base
        </button>
        <div className="grid grid-cols-3 gap-6">
          <div className="col-span-2 bg-card rounded-xl border border-border p-6">
            <div className="flex items-center gap-2 mb-2">
              <span className="text-lg">{countryFlags[selectedArticle.country]}</span>
              <span className="text-xs bg-muted px-2 py-0.5 rounded text-muted-foreground">{selectedArticle.category}</span>
              {selectedArticle.tags.map(t => <span key={t} className="text-xs bg-accent/60 px-2 py-0.5 rounded text-primary">{t}</span>)}
            </div>
            <h1 className="text-xl font-bold text-foreground mb-3">{selectedArticle.title}</h1>
            <div className="flex items-center gap-4 text-xs text-muted-foreground mb-6 pb-4 border-b border-border">
              <span>Updated {selectedArticle.updated}</span>
              <span>{selectedArticle.readTime} read</span>
              <span>{selectedArticle.views} views</span>
            </div>
            <div className="prose prose-sm max-w-none">
              {content.split("\n").map((line, i) => {
                if (line.startsWith("## ")) return <h2 key={i} className="text-base font-bold text-foreground mt-0 mb-3">{line.slice(3)}</h2>;
                if (line.startsWith("### ")) return <h3 key={i} className="text-sm font-semibold text-foreground mt-4 mb-2">{line.slice(4)}</h3>;
                if (line.startsWith("- ")) return <p key={i} className="text-sm text-foreground ml-3 my-0.5">• {line.slice(2)}</p>;
                if (/^\d+\./.test(line)) return <p key={i} className="text-sm text-foreground ml-3 my-0.5">{line}</p>;
                if (line === "") return <div key={i} className="h-2" />;
                return <p key={i} className="text-sm text-foreground my-1 leading-relaxed">{line}</p>;
              })}
            </div>
          </div>
          <div className="space-y-4">
            <div className="bg-card rounded-xl border border-border p-4">
              <h3 className="text-xs font-semibold text-foreground mb-3">Quick Actions</h3>
              <div className="space-y-2">
                <Btn variant="secondary" size="sm" className="w-full justify-start" onClick={() => {
                  const blob = new Blob([`# ${selectedArticle.title}\n\n${content}`], { type: "text/markdown;charset=utf-8;" });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement("a");
                  a.href = url; a.download = `${selectedArticle.title.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.md`; a.click();
                  setTimeout(() => URL.revokeObjectURL(url), 1000);
                  toast.success("Article downloaded");
                }}>
                  <Download className="w-3.5 h-3.5" />Download Article
                </Btn>
                <Btn variant="ghost" size="sm" className="w-full justify-start" onClick={() => { navigator.clipboard?.writeText(`https://app.stimes.pro/kb/${selectedArticle.id}`); toast.success("Shared link copied"); }}>
                  <Copy className="w-3.5 h-3.5" />Copy Link
                </Btn>
                <Btn variant="ghost" size="sm" className="w-full justify-start" onClick={() => toast.info("Feedback submitted")}>
                  <Star className="w-3.5 h-3.5" />Rate Article
                </Btn>
              </div>
            </div>
            <div className="bg-card rounded-xl border border-border p-4">
              <h3 className="text-xs font-semibold text-foreground mb-3">Related Articles</h3>
              <div className="space-y-2">
                {KB_ARTICLES.filter(a => a.category === selectedArticle.category && a.id !== selectedArticle.id).slice(0, 3).map(a => (
                  <button key={a.id} onClick={() => setSelectedArticle(a)} className="text-left w-full p-2 rounded-lg hover:bg-muted transition-colors">
                    <p className="text-xs font-medium text-foreground">{a.title}</p>
                    <p className="text-[10px] text-muted-foreground mt-0.5">{a.readTime} · {a.views} views</p>
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      <PageHeader title="Knowledge Base" subtitle="Internal SOPs, guides and country-specific procedures"
        actions={<Btn variant="secondary" size="sm"><FilePlus className="w-3.5 h-3.5" />New Article</Btn>}
      />
      {/* Search */}
      <div className="relative mb-5 max-w-lg">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <input type="text" value={search} onChange={e => setSearch(e.target.value)}
          placeholder="Search procedures, document types, countries…"
          className="w-full pl-10 pr-4 py-2.5 text-sm bg-card border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-ring/50" />
      </div>
      {/* Category tabs */}
      <div className="flex items-center gap-2 mb-5 overflow-x-auto pb-1">
        {categories.map(c => (
          <button key={c} onClick={() => setSelectedCategory(c)}
            className={`px-3 py-1.5 text-xs font-medium rounded-full whitespace-nowrap transition-colors border flex-shrink-0 ${selectedCategory === c ? "bg-primary text-white border-primary" : "bg-card text-muted-foreground border-border hover:border-primary/40"}`}>
            {c}
          </button>
        ))}
      </div>
      {/* Articles grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {filtered.map(article => (
          <button key={article.id} onClick={() => setSelectedArticle(article)}
            className="text-left bg-card rounded-xl border border-border p-5 hover:shadow-md hover:border-primary/30 transition-all group">
            <div className="flex items-start justify-between mb-3">
              <span className="text-2xl">{countryFlags[article.country]}</span>
              <span className="text-[10px] text-muted-foreground">{article.views} views</span>
            </div>
            <h3 className="text-sm font-semibold text-foreground group-hover:text-primary transition-colors mb-2 leading-snug">{article.title}</h3>
            <div className="flex flex-wrap gap-1 mb-3">
              {article.tags.map(t => <span key={t} className="text-[10px] bg-muted px-1.5 py-0.5 rounded text-muted-foreground">{t}</span>)}
            </div>
            <div className="flex items-center gap-3 text-[10px] text-muted-foreground">
              <span className="flex items-center gap-1"><Clock className="w-3 h-3" />{article.readTime}</span>
              <span>Updated {article.updated}</span>
            </div>
          </button>
        ))}
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// COUNTRY RULE ENGINE SCREEN
// ─────────────────────────────────────────────────────────────
const COUNTRY_RULES = [
  {
    id: "cr_sa", country: "Saudi Arabia", code: "SA", flag: "🇸🇦", active: true,
    docTypes: ["Iqama","Work Visa","Exit/Re-entry","GOSI","Commercial Register","Municipal License","Work Permit"],
    portals: ["Absher Business","Muqeem","MOCI Portal","GOSI Platform","Jawazat"],
    fees: { iqama: 650, workVisa: 2000, exitReentry: 200, cr: 1200 },
    timelines: { iqama: 14, workVisa: 21, cr: 30, exitReentry: 3 },
    requiredDocs: ["Valid Passport","Medical Certificate","Employer Letter","GOSI Certificate"],
  },
];

function CountryRuleEngineScreen() {
  const [selected, setSelected] = useState(COUNTRY_RULES[0]);
  const [editMode, setEditMode] = useState(false);
  const [countries, setCountries] = useState(COUNTRY_RULES);

  const current = countries.find(c => c.id === selected.id) || selected;

  const toggleActive = (id: string) => {
    setCountries(prev => prev.map(c => c.id === id ? { ...c, active: !c.active } : c));
    toast.success("Country rule status updated");
  };

  const addCountry = () => {
    const name = window.prompt("Country name?")?.trim();
    if (!name) return;
    const code = (window.prompt("2-letter country code?", name.slice(0, 2).toUpperCase())?.trim() || name.slice(0, 2)).toUpperCase();
    const newCountry = { id: `cr_${Date.now()}`, country: name, code, flag: "🏳️", active: false, docTypes: [] as string[], portals: [] as string[], fees: {}, timelines: {}, requiredDocs: [] as string[] };
    setCountries(prev => [...prev, newCountry]);
    setSelected(newCountry);
    setEditMode(true);
    toast.success(`${name} added`);
  };

  const addDocType = () => {
    const d = window.prompt("New document type name?")?.trim();
    if (!d) return;
    if (current.docTypes.includes(d)) { toast.error("Document type already exists"); return; }
    setCountries(prev => prev.map(c => c.id === current.id ? { ...c, docTypes: [...c.docTypes, d] } : c));
    toast.success(`${d} added`);
  };

  const removeDocType = (d: string) => {
    setCountries(prev => prev.map(c => c.id === current.id ? { ...c, docTypes: c.docTypes.filter(x => x !== d) } : c));
    toast.success(`${d} removed`);
  };

  return (
    <div>
      <PageHeader title="Country Rule Engine" subtitle="Configure per-country document types, timelines, fees and portals"
        actions={<Btn variant="secondary" size="sm" onClick={addCountry}><Plus className="w-3.5 h-3.5" />Add Country</Btn>}
      />
      <div className="flex gap-5">
        {/* Country list */}
        <div className="w-52 flex-shrink-0 space-y-1">
          {countries.map(c => (
            <button key={c.id} onClick={() => setSelected(c)}
              className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border text-left transition-all ${current.id === c.id ? "border-primary bg-accent text-foreground" : "border-border bg-card text-muted-foreground hover:bg-muted"}`}>
              <span className="text-xl">{c.flag}</span>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate">{c.country}</p>
                <p className="text-[10px]">{c.docTypes.length} doc types</p>
              </div>
              <span className={`w-2 h-2 rounded-full flex-shrink-0 ${c.active ? "bg-emerald-500" : "bg-gray-300"}`} />
            </button>
          ))}
        </div>

        {/* Detail panel */}
        <div className="flex-1 space-y-4">
          {/* Header card */}
          <div className="bg-card rounded-xl border border-border p-5">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-3">
                <span className="text-3xl">{current.flag}</span>
                <div>
                  <h2 className="text-base font-bold text-foreground">{current.country}</h2>
                  <p className="text-xs text-muted-foreground">{current.docTypes.length} document types · {current.portals.length} portals</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <label className="flex items-center gap-2 cursor-pointer">
                  <span className="text-xs text-muted-foreground">Active</span>
                  <div onClick={() => toggleActive(current.id)} className={`w-10 h-5 rounded-full transition-colors cursor-pointer ${current.active ? "bg-primary" : "bg-gray-200"}`}>
                    <div className={`w-4 h-4 rounded-full bg-white shadow m-0.5 transition-transform ${current.active ? "translate-x-5" : ""}`} />
                  </div>
                </label>
                <Btn variant="secondary" size="sm" onClick={() => setEditMode(!editMode)}>
                  <Pencil className="w-3.5 h-3.5" />{editMode ? "Save" : "Edit"}
                </Btn>
              </div>
            </div>

            {/* Document types */}
            <div className="mb-4">
              <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Document Types</h3>
              <div className="flex flex-wrap gap-2">
                {current.docTypes.map(d => (
                  <div key={d} className="flex items-center gap-1.5 bg-muted px-3 py-1.5 rounded-lg text-xs font-medium text-foreground">
                    {d}
                    {editMode && <button onClick={() => removeDocType(d)} className="text-muted-foreground hover:text-red-500 ml-1"><X className="w-3 h-3" /></button>}
                  </div>
                ))}
                {editMode && (
                  <button className="flex items-center gap-1.5 border border-dashed border-border px-3 py-1.5 rounded-lg text-xs text-muted-foreground hover:border-primary hover:text-primary transition-colors" onClick={addDocType}>
                    <Plus className="w-3 h-3" />Add
                  </button>
                )}
              </div>
            </div>

            {/* Portals */}
            <div>
              <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Government Portals</h3>
              <div className="flex flex-wrap gap-2">
                {current.portals.map(p => (
                  <span key={p} className="flex items-center gap-1.5 bg-accent/60 px-3 py-1.5 rounded-lg text-xs font-medium text-primary">
                    <Globe2 className="w-3 h-3" />{p}
                  </span>
                ))}
              </div>
            </div>
          </div>

          {/* Fees & Timelines */}
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-card rounded-xl border border-border p-5">
              <h3 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
                <DollarSign className="w-4 h-4 text-primary" />Fees (SAR equivalent)
              </h3>
              <div className="space-y-2">
                {Object.entries(current.fees).map(([key, val]) => (
                  <div key={key} className="flex items-center justify-between py-1.5 border-b border-border/40 last:border-0">
                    <span className="text-xs text-muted-foreground capitalize">{key.replace(/([A-Z])/g, " $1")}</span>
                    {editMode
                      ? <input defaultValue={val} className="w-20 text-right text-xs bg-muted border border-border rounded px-2 py-1 focus:outline-none" />
                      : <span className="text-sm font-semibold text-foreground">SAR {val.toLocaleString()}</span>
                    }
                  </div>
                ))}
              </div>
            </div>
            <div className="bg-card rounded-xl border border-border p-5">
              <h3 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
                <Timer className="w-4 h-4 text-primary" />Timelines (working days)
              </h3>
              <div className="space-y-2">
                {Object.entries(current.timelines).map(([key, val]) => (
                  <div key={key} className="flex items-center justify-between py-1.5 border-b border-border/40 last:border-0">
                    <span className="text-xs text-muted-foreground capitalize">{key.replace(/([A-Z])/g, " $1")}</span>
                    {editMode
                      ? <input defaultValue={val} className="w-16 text-right text-xs bg-muted border border-border rounded px-2 py-1 focus:outline-none" />
                      : <span className="text-sm font-semibold text-foreground">{val}d</span>
                    }
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Required docs */}
          <div className="bg-card rounded-xl border border-border p-5">
            <h3 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
              <FileText className="w-4 h-4 text-primary" />Required Documents (standard)
            </h3>
            <div className="grid grid-cols-2 gap-2">
              {current.requiredDocs.map(d => (
                <div key={d} className="flex items-center gap-2 text-sm text-foreground">
                  <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500 flex-shrink-0" />{d}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// DOCUMENT TEMPLATES SCREEN
// ─────────────────────────────────────────────────────────────
interface DocTemplate { id: string; name: string; type: string; category: string; lang: string; lastUpdated: string; usedCount: number; }
const DOC_TEMPLATES_DATA: DocTemplate[] = [];

// Document Types manager — define document types + their dynamic fields (Expiry Date is always captured separately).
function DocumentTypesScreen() {
  const [types, setTypes] = useState<DocType[]>(DOCUMENT_TYPES);
  useEffect(() => { (async () => { try { const d = await api.get("/api/document-types"); if (Array.isArray(d)) { const list = d.map((t: any) => ({ ...t, fields: Array.isArray(t.fields) ? t.fields : [] })); setTypes(list); setDocumentTypesCatalog(list); } } catch { /* keep cached */ } })(); }, []);
  const sync = (list: DocType[]) => { setTypes(list); setDocumentTypesCatalog(list); };
  const [editing, setEditing] = useState<DocType | null>(null);
  const [isNew, setIsNew] = useState(false);
  const openNew = () => { setIsNew(true); setEditing({ id: `dt${Date.now()}`, name: "", fields: [], prereqs: [] }); };
  const openEdit = (t: DocType) => { setIsNew(false); setEditing({ ...t, fields: t.fields.map(f => ({ ...f })), prereqs: (t.prereqs ?? []).map(p => ({ ...p })) }); };
  const setField = (i: number, patch: Partial<DocFieldDef>) => setEditing(e => e ? { ...e, fields: e.fields.map((f, j) => j === i ? { ...f, ...patch } : f) } : e);
  const addFieldRow = () => setEditing(e => e ? { ...e, fields: [...e.fields, { id: `f${Date.now()}`, label: "", type: "text", required: false }] } : e);
  const removeFieldRow = (i: number) => setEditing(e => e ? { ...e, fields: e.fields.filter((_, j) => j !== i) } : e);
  const setPrereq = (i: number, patch: Partial<DocPrereq>) => setEditing(e => e ? { ...e, prereqs: (e.prereqs ?? []).map((p, j) => j === i ? { ...p, ...patch } : p) } : e);
  const addPrereqRow = () => setEditing(e => e ? { ...e, prereqs: [...(e.prereqs ?? []), { requiresDocType: "", minMonths: 6 }] } : e);
  const removePrereqRow = (i: number) => setEditing(e => e ? { ...e, prereqs: (e.prereqs ?? []).filter((_, j) => j !== i) } : e);
  const save = async () => {
    if (!editing) return;
    if (!editing.name.trim()) { toast.error("Document type name is required"); return; }
    if (types.find(t => t.id !== editing.id && t.name.trim().toLowerCase() === editing.name.trim().toLowerCase())) { toast.error("A document type with this name already exists"); return; }
    const prereqs = (editing.prereqs ?? []).filter(p => p.requiresDocType.trim()).map(p => ({ requiresDocType: p.requiresDocType.trim(), minMonths: Math.max(0, Number(p.minMonths) || 0) }));
    const cfg = { leadDays: editing.leadDays ? Math.max(0, Number(editing.leadDays)) : undefined, defaultFee: editing.defaultFee ? Math.max(0, Number(editing.defaultFee)) : undefined, requiresApproval: !!editing.requiresApproval, defaultAssigneeRole: editing.defaultAssigneeRole || undefined, subjectKind: editing.subjectKind === "company" ? "company" : "employee" };
    const clean: DocType = { ...editing, name: editing.name.trim(), fields: editing.fields.filter(f => f.label.trim()).map(f => ({ ...f, label: f.label.trim(), options: f.type === "dropdown" ? (f.options ?? []).map(o => o.trim()).filter(Boolean) : undefined })), prereqs, ...cfg };
    if (isNew) {
      try { const res = await api.post("/api/document-types", { id: clean.id, name: clean.name, fields: clean.fields, prereqs, ...cfg }); if (res?.id) clean.id = res.id; } catch { toast.error("Server unreachable — saved locally only"); }
      sync([...types, clean]); toast.success("Document type added");
    } else {
      try { await api.put(`/api/document-types/${clean.id}`, { name: clean.name, fields: clean.fields, prereqs, ...cfg }); } catch { toast.error("Server unreachable — saved locally only"); }
      sync(types.map(t => t.id === clean.id ? clean : t)); toast.success("Document type updated");
    }
    setEditing(null);
  };
  const remove = async (t: DocType) => { try { await api.del(`/api/document-types/${t.id}`); } catch { /* removed locally */ } sync(types.filter(x => x.id !== t.id)); toast.success("Document type removed"); };
  return (
    <div>
      <PageHeader title="Document Types" subtitle="Define the document types tracked for clients and the extra fields captured for each. Expiry Date is always captured and drives Compliance."
        actions={<Btn variant="primary" size="sm" onClick={openNew}><Plus className="w-3.5 h-3.5" />Add Type</Btn>} />
      {types.length === 0 ? (
        <div className="bg-card rounded-xl border border-border"><div className="p-4"><EmptyState icon={FileCheck} title="No document types yet" message="Add types like Iqama, Work Visa, GOSI — each with its own fields. They appear when adding a document under a client." action={<Btn variant="primary" size="sm" onClick={openNew}><Plus className="w-3.5 h-3.5" />Add Type</Btn>} /></div></div>
      ) : (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {types.map(t => (
            <div key={t.id} className="bg-card rounded-xl border border-border p-4 flex flex-col">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-2.5 min-w-0"><span className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0"><FileCheck className="w-4 h-4 text-primary" /></span><p className="text-sm font-semibold text-foreground truncate">{t.name}</p></div>
                <div className="flex gap-1 flex-shrink-0">
                  <button onClick={() => openEdit(t)} className="p-1.5 rounded hover:bg-muted text-muted-foreground" title="Edit"><Pencil className="w-3.5 h-3.5" /></button>
                  <button onClick={() => remove(t)} className="p-1.5 rounded hover:bg-red-50 hover:text-red-500 text-muted-foreground" title="Remove"><Trash2 className="w-3.5 h-3.5" /></button>
                </div>
              </div>
              <p className="text-[11px] text-muted-foreground mt-2">Expiry Date{t.fields.length ? ` · ${t.fields.map(f => f.label).join(" · ")}` : " (no extra fields)"}</p>
            </div>
          ))}
        </div>
      )}
      <Modal open={!!editing} onClose={() => setEditing(null)} title={isNew ? "New document type" : "Edit document type"} wide>
        {editing && (
          <div className="space-y-4">
            <div><label className="block text-xs font-medium text-foreground mb-1">Type name *</label>
              <input value={editing.name} autoFocus onChange={e => setEditing(x => x ? { ...x, name: e.target.value } : x)} placeholder="e.g. Work Visa" className="w-full px-3 py-2 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50" /></div>
            <div>
              <div className="flex items-center justify-between mb-1.5">
                <label className="block text-xs font-medium text-foreground">Extra fields <span className="text-muted-foreground font-normal">(captured when adding this document)</span></label>
                <Btn variant="ghost" size="xs" onClick={addFieldRow}><Plus className="w-3 h-3" />Add field</Btn>
              </div>
              <p className="text-[11px] text-muted-foreground mb-2">Expiry Date is always captured automatically. Add any extra fields below (e.g. Visa Number, Sponsor).</p>
              {editing.fields.length === 0 ? (
                <p className="text-[11px] text-muted-foreground py-2">No extra fields — only Expiry Date will be captured.</p>
              ) : (
                <div className="space-y-2">
                  {editing.fields.map((f, i) => (
                    <div key={f.id} className="border border-border rounded-lg p-2.5 space-y-2">
                      <div className="flex gap-2 items-center">
                        <input value={f.label} onChange={e => setField(i, { label: e.target.value })} placeholder="Field label (e.g. Visa Number)" className="flex-1 px-2.5 py-1.5 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50" />
                        <select value={f.type} onChange={e => setField(i, { type: e.target.value as DocFieldDef["type"] })} className="px-2.5 py-1.5 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50">
                          <option value="text">Text</option><option value="number">Number</option><option value="date">Date</option><option value="dropdown">Dropdown</option>
                        </select>
                        <label className="flex items-center gap-1.5 text-xs text-foreground cursor-pointer whitespace-nowrap"><input type="checkbox" checked={!!f.required} onChange={e => setField(i, { required: e.target.checked })} />Req</label>
                        <button onClick={() => removeFieldRow(i)} className="p-1.5 rounded hover:bg-red-50 hover:text-red-500 text-muted-foreground" title="Remove"><Trash2 className="w-3.5 h-3.5" /></button>
                      </div>
                      {f.type === "dropdown" && (
                        <input value={(f.options ?? []).join(", ")} onChange={e => setField(i, { options: e.target.value.split(/,\s*/) })} placeholder="Options, comma-separated (e.g. New, Renewal)" className="w-full px-2.5 py-1.5 text-xs border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50" />
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
            {/* Subject — who the document belongs to. Person docs (Iqama, visa) attach to an employee;
                company docs (CR, GOSI, VAT) attach to the company itself. Drives every intake + workflow. */}
            <div className="border-t border-border pt-3">
              <label className="block text-xs font-medium text-foreground mb-2">Document belongs to</label>
              <div className="grid grid-cols-2 gap-2">
                {([["employee", "An employee", "Iqama, Work Visa, Passport — attached to a person"], ["company", "The company", "CR, GOSI, VAT — attached to the client itself"]] as const).map(([val, title, hint]) => {
                  const on = (editing.subjectKind ?? "employee") === val;
                  return (
                    <button key={val} type="button" onClick={() => setEditing(x => x ? { ...x, subjectKind: val } : x)}
                      className={`text-left rounded-lg border p-2.5 transition ${on ? "border-primary bg-primary/5 ring-1 ring-primary/30" : "border-border bg-muted hover:border-primary/40"}`}>
                      <div className="flex items-center gap-1.5">{on ? <CheckCircle2 className="w-3.5 h-3.5 text-primary" /> : <Square className="w-3.5 h-3.5 text-muted-foreground" />}<span className="text-xs font-semibold text-foreground">{title}</span></div>
                      <p className="text-[10px] text-muted-foreground mt-0.5">{hint}</p>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Per-type renewal config — drives reminders, task defaults and approval */}
            <div className="border-t border-border pt-3">
              <label className="block text-xs font-medium text-foreground mb-2">Renewal configuration</label>
              <div className="grid grid-cols-2 gap-3">
                <div><label className="block text-[11px] text-muted-foreground mb-1">Reminder lead time (days)</label>
                  <input type="number" value={editing.leadDays ?? ""} onChange={e => setEditing(x => x ? { ...x, leadDays: e.target.value ? Number(e.target.value) : undefined } : x)} placeholder="30" className="w-full px-2 py-1.5 text-xs border border-border rounded-lg bg-muted" />
                  <p className="text-[10px] text-muted-foreground mt-0.5">Flags "Expiring" this many days before expiry (e.g. Iqama 60, Passport 180).</p></div>
                <div><label className="block text-[11px] text-muted-foreground mb-1">Default renewal fee (SAR)</label>
                  <input type="number" value={editing.defaultFee ?? ""} onChange={e => setEditing(x => x ? { ...x, defaultFee: e.target.value ? Number(e.target.value) : undefined } : x)} placeholder="0" className="w-full px-2 py-1.5 text-xs border border-border rounded-lg bg-muted" /></div>
                <div><label className="block text-[11px] text-muted-foreground mb-1">Default assignee role</label>
                  <select value={editing.defaultAssigneeRole ?? ""} onChange={e => setEditing(x => x ? { ...x, defaultAssigneeRole: e.target.value || undefined } : x)} className="w-full px-2 py-1.5 text-xs border border-border rounded-lg bg-muted">
                    <option value="">— any —</option><option value="pro_officer">PRO Officer</option><option value="admin">Admin</option><option value="super_admin">Super Admin</option>
                  </select></div>
                <div className="flex items-end pb-1"><label className="flex items-center gap-2 text-xs text-foreground cursor-pointer"><input type="checkbox" checked={!!editing.requiresApproval} onChange={e => setEditing(x => x ? { ...x, requiresApproval: e.target.checked } : x)} className="accent-primary" />Renewal needs approval</label></div>
              </div>
            </div>
            {/* Renewal prerequisites — block renewal unless a related doc has enough validity */}
            <div className="border-t border-border pt-3">
              <div className="flex items-center justify-between mb-1.5">
                <label className="block text-xs font-medium text-foreground">Renewal prerequisites <span className="text-muted-foreground font-normal">(optional)</span></label>
                <Btn variant="ghost" size="xs" onClick={addPrereqRow}><Plus className="w-3 h-3" />Add rule</Btn>
              </div>
              <p className="text-[11px] text-muted-foreground mb-2">Require another document to have a minimum remaining validity before this one can be renewed (e.g. Passport ≥ 6 months).</p>
              {(editing.prereqs ?? []).length === 0 ? (
                <p className="text-[11px] text-muted-foreground py-1">No prerequisites — this document can be renewed anytime.</p>
              ) : (
                <div className="space-y-2">
                  {(editing.prereqs ?? []).map((p, i) => (
                    <div key={i} className="flex gap-2 items-center flex-wrap">
                      <span className="text-xs text-muted-foreground">Requires</span>
                      <select value={p.requiresDocType} onChange={e => setPrereq(i, { requiresDocType: e.target.value })} className="px-2.5 py-1.5 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50">
                        <option value="">Document type…</option>
                        {docTypeNames().filter(n => n !== editing.name).map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                      <span className="text-xs text-muted-foreground">to have ≥</span>
                      <input type="number" min={0} value={p.minMonths} onChange={e => setPrereq(i, { minMonths: Number(e.target.value) })} className="w-16 px-2.5 py-1.5 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50" />
                      <span className="text-xs text-muted-foreground">months validity</span>
                      <button onClick={() => removePrereqRow(i)} className="p-1.5 rounded hover:bg-red-50 hover:text-red-500 text-muted-foreground ml-auto" title="Remove"><Trash2 className="w-3.5 h-3.5" /></button>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div className="flex items-center justify-end gap-2 pt-2 border-t border-border">
              <Btn variant="secondary" onClick={() => setEditing(null)}>Cancel</Btn>
              <Btn variant="primary" onClick={save}><CheckCircle2 className="w-3.5 h-3.5" />{isNew ? "Add type" : "Save type"}</Btn>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

function DocTemplatesScreen() {
  const [search, setSearch] = useState("");
  const [catFilter, setCatFilter] = useState("All");
  const [templates, setTemplates] = useState<DocTemplate[]>(DOC_TEMPLATES_DATA);
  const [editing, setEditing] = useState<DocTemplate | null>(null);
  const [isNew, setIsNew] = useState(false);
  const [preview, setPreview] = useState<DocTemplate | null>(null);

  const categories = ["All", "Government Forms", "Finance", "Communications", "Checklists", "HR & Onboarding"];
  const typeColors: Record<string, string> = {
    PDF: "bg-red-50 text-red-700", Email: "bg-blue-50 text-blue-700", Government: "bg-amber-50 text-amber-700",
  };

  const filtered = templates.filter(t =>
    (catFilter === "All" || t.category === catFilter) &&
    t.name.toLowerCase().includes(search.toLowerCase())
  );

  const openNew = () => { setIsNew(true); setEditing({ id: `dt${Date.now()}`, name: "", type: "PDF", category: "Government Forms", lang: "EN", lastUpdated: "Today", usedCount: 0 }); };
  const saveTemplate = () => {
    if (!editing) return;
    if (!editing.name.trim()) { toast.error("Template name is required"); return; }
    if (isNew) { setTemplates(prev => [editing, ...prev]); toast.success("Template created"); }
    else { setTemplates(prev => prev.map(t => t.id === editing.id ? editing : t)); toast.success("Template saved"); }
    setEditing(null); setIsNew(false);
  };
  const duplicateTemplate = (t: DocTemplate) => {
    setTemplates(prev => [{ ...t, id: `dt${Date.now()}`, name: `${t.name} (Copy)`, usedCount: 0, lastUpdated: "Today" }, ...prev]);
    toast.success("Template duplicated");
  };

  return (
    <div>
      <PageHeader title="Document Templates" subtitle="PDF, email and government-form templates"
        actions={<Btn variant="primary" size="sm" onClick={openNew}><Plus className="w-3.5 h-3.5" />New Template</Btn>}
      />
      <div className="flex items-center gap-3 mb-4">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
          <input type="text" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search templates…"
            className="w-full pl-9 pr-3 py-2 text-sm bg-card border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/50" />
        </div>
        <div className="flex items-center gap-2 overflow-x-auto">
          {categories.map(c => (
            <button key={c} onClick={() => setCatFilter(c)}
              className={`px-3 py-1.5 text-xs font-medium rounded-full whitespace-nowrap transition-colors border flex-shrink-0 ${catFilter === c ? "bg-primary text-white border-primary" : "bg-card text-muted-foreground border-border hover:border-primary/40"}`}>
              {c}
            </button>
          ))}
        </div>
      </div>
      <div className="bg-card rounded-xl border border-border overflow-hidden flex flex-col" style={{ height: TABLE_MIN_H }}>
        <div className="overflow-x-auto flex-1" style={{ overflowY: "auto" }}>
        <table className="w-full">
          <thead>
            <tr className="border-b border-border bg-muted/30">
              {["Template Name","Type","Category","Language","Last Updated","Used","_dt_act"].map(h => (
                <th key={h} className="text-left py-3 px-4 text-xs font-semibold text-muted-foreground">{h.startsWith("_") ? "" : h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map(t => (
              <tr key={t.id} className="border-b border-border/60 hover:bg-muted/30 transition-colors group">
                <td className="py-3 px-4">
                  <div className="flex items-center gap-2">
                    <FileText className="w-4 h-4 text-muted-foreground" />
                    <span className="text-sm font-medium text-foreground">{t.name}</span>
                  </div>
                </td>
                <td className="py-3 px-4">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${typeColors[t.type] || "bg-gray-100 text-gray-600"}`}>{t.type}</span>
                </td>
                <td className="py-3 px-4 text-sm text-muted-foreground">{t.category}</td>
                <td className="py-3 px-4"><span className="text-xs font-mono bg-muted px-2 py-0.5 rounded">{t.lang}</span></td>
                <td className="py-3 px-4 text-xs text-muted-foreground">{t.lastUpdated}</td>
                <td className="py-3 px-4 text-sm font-medium text-foreground">{t.usedCount}×</td>
                <td className="py-3 px-4">
                  <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Btn variant="secondary" size="xs" onClick={() => { setIsNew(false); setEditing(t); }}>
                      <Pencil className="w-3 h-3" />Edit
                    </Btn>
                    <Btn variant="ghost" size="xs" onClick={() => setPreview(t)}>
                      <Eye className="w-3 h-3" />Preview
                    </Btn>
                    <Btn variant="ghost" size="xs" onClick={() => duplicateTemplate(t)}>
                      <Copy className="w-3 h-3" />Clone
                    </Btn>
                  </div>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={7}><EmptyState icon={FileCheck} title={search || catFilter !== "All" ? "No templates match your filters" : "No templates yet"} message={search || catFilter !== "All" ? "Try a different search or category." : "Create your first document or email template."} /></td></tr>
            )}
          </tbody>
        </table>
        </div>
      </div>

      {/* New / Edit template modal */}
      <Modal open={!!editing} onClose={() => { setEditing(null); setIsNew(false); }} title={isNew ? "New Template" : "Edit Template"}>
        {editing && (
          <div className="space-y-3">
            <div>
              <label className="block text-xs font-semibold text-muted-foreground mb-1">Template Name *</label>
              <input value={editing.name} onChange={e => setEditing({ ...editing, name: e.target.value })}
                placeholder="e.g. Iqama Renewal Cover Letter"
                className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/40" />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-semibold text-muted-foreground mb-1">Type</label>
                <select value={editing.type} onChange={e => setEditing({ ...editing, type: e.target.value })}
                  className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/40">
                  {["PDF","Email","Government"].map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs font-semibold text-muted-foreground mb-1">Category</label>
                <select value={editing.category} onChange={e => setEditing({ ...editing, category: e.target.value })}
                  className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/40">
                  {categories.filter(c => c !== "All").map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>
            </div>
            <div>
              <label className="block text-xs font-semibold text-muted-foreground mb-1">Language</label>
              <select value={editing.lang} onChange={e => setEditing({ ...editing, lang: e.target.value })}
                className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/40">
                {["EN","AR","EN/AR","AR/EN"].map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="flex gap-2 mt-4">
              <Btn variant="ghost" size="sm" className="flex-1" onClick={() => { setEditing(null); setIsNew(false); }}>Cancel</Btn>
              <Btn variant="primary" size="sm" className="flex-1" onClick={saveTemplate}>{isNew ? "Create Template" : "Save Changes"}</Btn>
            </div>
          </div>
        )}
      </Modal>

      {/* Preview modal */}
      <Modal open={!!preview} onClose={() => setPreview(null)} title={preview?.name || "Preview"}>
        {preview && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-3 text-sm">
              {[{ label: "Type", value: preview.type }, { label: "Category", value: preview.category }, { label: "Language", value: preview.lang }, { label: "Last Updated", value: preview.lastUpdated }, { label: "Used", value: `${preview.usedCount}×` }].map(f => (
                <div key={f.label}><p className="text-xs text-muted-foreground mb-0.5">{f.label}</p><p className="text-sm font-medium text-foreground">{f.value}</p></div>
              ))}
            </div>
            <div className="bg-muted rounded-lg border border-border p-6 text-center text-sm text-muted-foreground">
              <FileText className="w-8 h-8 mx-auto mb-2 text-muted-foreground/60" />
              Rendered preview of “{preview.name}” would appear here.
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// MULTI-TENANT ADMIN SCREEN
// ─────────────────────────────────────────────────────────────
const TENANTS = [
  { id: "t1", name: "STIMES PRO — Riyadh", plan: "Enterprise", users: 24, clients: 67, storage: "12.4 GB", storageLimit: "50 GB", active: true, since: "Jan 2023", logo: "🏢", color: "#7105ef" },
  { id: "t2", name: "Al-Nawras PRO — Jeddah", plan: "Professional", users: 8, clients: 23, storage: "3.2 GB", storageLimit: "20 GB", active: true, since: "Mar 2024", logo: "🏬", color: "#2563eb" },
  { id: "t3", name: "Gulf Services — Dubai", plan: "Professional", users: 12, clients: 31, storage: "5.8 GB", storageLimit: "20 GB", active: true, since: "Jun 2024", logo: "🏙️", color: "#059669" },
  { id: "t4", name: "Horizon PRO — Doha", plan: "Starter", users: 3, clients: 7, storage: "0.9 GB", storageLimit: "5 GB", active: false, since: "Oct 2024", logo: "🏗️", color: "#d97706" },
  { id: "t5", name: "ProVisa Solutions — Kuwait", plan: "Starter", users: 2, clients: 5, storage: "0.4 GB", storageLimit: "5 GB", active: true, since: "Nov 2024", logo: "🏛️", color: "#7c3aed" },
];

const PLAN_COLORS: Record<string, string> = {
  Enterprise: "bg-violet-50 text-violet-700 ring-violet-600/20",
  Professional: "bg-blue-50 text-blue-700 ring-blue-600/20",
  Starter: "bg-gray-100 text-gray-600 ring-gray-400/20",
};

type Tenant = typeof TENANTS[number];

function MultiTenantScreen() {
  const [tenants, setTenants] = useState(TENANTS);
  const [selected, setSelected] = useState<Tenant | null>(null);
  const [draft, setDraft] = useState<{ name: string; plan: string; color: string }>({ name: "", plan: "Starter", color: "#7105ef" });
  const [showAddTenant, setShowAddTenant] = useState(false);
  const [newTenant, setNewTenant] = useState({ name: "", plan: "Starter" });

  const openTenant = (t: Tenant) => { setSelected(t); setDraft({ name: t.name, plan: t.plan, color: t.color }); };
  const saveTenant = () => {
    if (!selected) return;
    setTenants(prev => prev.map(x => x.id === selected.id ? { ...x, name: draft.name, plan: draft.plan, color: draft.color } : x));
    setSelected(null);
    toast.success("Changes saved");
  };

  const totalUsers = tenants.reduce((s, t) => s + t.users, 0);
  const totalClients = tenants.reduce((s, t) => s + t.clients, 0);
  const activeCount = tenants.filter(t => t.active).length;

  return (
    <div>
      <PageHeader title="Multi-Tenant Admin" subtitle="Manage organizations, subscriptions and usage"
        actions={<Btn variant="primary" size="sm" onClick={() => { setNewTenant({ name: "", plan: "Starter" }); setShowAddTenant(true); }}><Plus className="w-3.5 h-3.5" />Add Tenant</Btn>}
      />

      {/* Summary */}
      <div className="grid grid-cols-4 gap-4 mb-6">
        {[
          { label: "Total Tenants", value: tenants.length, icon: PackageIcon, color: "text-primary", bg: "bg-accent" },
          { label: "Active", value: activeCount, icon: CheckCircle2, color: "text-emerald-600", bg: "bg-green-50" },
          { label: "Total Users", value: totalUsers, icon: UsersIcon, color: "text-blue-600", bg: "bg-blue-50" },
          { label: "Total Clients", value: totalClients, icon: Building2, color: "text-amber-600", bg: "bg-amber-50" },
        ].map(s => (
          <div key={s.label} className="bg-card rounded-xl border border-border p-4">
            <div className={`w-9 h-9 rounded-lg ${s.bg} flex items-center justify-center mb-3`}>
              <s.icon className={`w-4.5 h-4.5 w-[18px] h-[18px] ${s.color}`} />
            </div>
            <p className="text-2xl font-bold text-foreground">{s.value}</p>
            <p className="text-xs text-muted-foreground">{s.label}</p>
          </div>
        ))}
      </div>

      {/* Tenant table */}
      <div className="bg-card rounded-xl border border-border overflow-hidden flex flex-col" style={{ height: TABLE_MIN_H }}>
        <div className="overflow-x-auto flex-1" style={{ overflowY: "auto" }}>
        <table className="w-full">
          <thead>
            <tr className="border-b border-border bg-muted/30">
              {["Organization","Plan","Users","Clients","Storage","Since","Status","_mt_act"].map(h => (
                <th key={h} className="text-left py-3 px-4 text-xs font-semibold text-muted-foreground">{h.startsWith("_") ? "" : h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {tenants.map(t => {
              const storageUsed = parseFloat(t.storage);
              const storageLimit = parseFloat(t.storageLimit);
              const pct = Math.round((storageUsed / storageLimit) * 100);
              return (
                <tr key={t.id} className="border-b border-border/60 hover:bg-muted/30 transition-colors group">
                  <td className="py-3 px-4">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-lg flex items-center justify-center text-base" style={{ backgroundColor: t.color + "20" }}>
                        {t.logo}
                      </div>
                      <div>
                        <p className="text-sm font-medium text-foreground">{t.name}</p>
                      </div>
                    </div>
                  </td>
                  <td className="py-3 px-4">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ring-1 ring-inset ${PLAN_COLORS[t.plan]}`}>{t.plan}</span>
                  </td>
                  <td className="py-3 px-4 text-sm font-medium text-foreground">{t.users}</td>
                  <td className="py-3 px-4 text-sm font-medium text-foreground">{t.clients}</td>
                  <td className="py-3 px-4">
                    <div>
                      <div className="flex justify-between text-xs mb-1">
                        <span className="text-foreground">{t.storage}</span>
                        <span className="text-muted-foreground">{pct}%</span>
                      </div>
                      <div className="w-24 bg-muted rounded-full h-1.5">
                        <div className={`h-1.5 rounded-full ${pct > 80 ? "bg-red-500" : pct > 60 ? "bg-amber-400" : "bg-emerald-500"}`} style={{ width: `${pct}%` }} />
                      </div>
                    </div>
                  </td>
                  <td className="py-3 px-4 text-xs text-muted-foreground">{t.since}</td>
                  <td className="py-3 px-4">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ring-1 ring-inset ${t.active ? "bg-green-50 text-green-700 ring-green-600/20" : "bg-gray-100 text-gray-500 ring-gray-400/20"}`}>
                      {t.active ? "Active" : "Inactive"}
                    </span>
                  </td>
                  <td className="py-3 px-4">
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <Btn variant="secondary" size="xs" onClick={() => openTenant(t)}>Manage</Btn>
                      <Btn variant="ghost" size="xs" onClick={() => { setTenants(prev => prev.map(x => x.id === t.id ? { ...x, active: !x.active } : x)); toast.success("Status updated"); }}>
                        {t.active ? "Suspend" : "Activate"}
                      </Btn>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        </div>
      </div>

      {/* Tenant detail modal */}
      <Modal open={!!selected} onClose={() => setSelected(null)} title={selected?.name || ""} wide>
        {selected && (
          <div className="space-y-5">
            <div className="grid grid-cols-3 gap-4">
              {[{ label: "Plan", value: selected.plan }, { label: "Users", value: String(selected.users) }, { label: "Clients Managed", value: String(selected.clients) }].map(i => (
                <div key={i.label} className="bg-muted rounded-xl p-4">
                  <p className="text-xs text-muted-foreground mb-1">{i.label}</p>
                  <p className="text-xl font-bold text-foreground">{i.value}</p>
                </div>
              ))}
            </div>
            <div>
              <h3 className="text-sm font-semibold text-foreground mb-2">Branding</h3>
              <div className="flex items-center gap-3 p-3 bg-muted rounded-xl">
                <div className="w-10 h-10 rounded-lg flex items-center justify-center text-xl" style={{ backgroundColor: draft.color + "20" }}>{selected.logo}</div>
                <div className="flex-1 space-y-2">
                  <input value={draft.name} onChange={e => setDraft(d => ({ ...d, name: e.target.value }))}
                    className="w-full px-2.5 py-1.5 text-sm bg-card border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/40" />
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground">Primary color</span>
                    <input type="color" value={draft.color} onChange={e => setDraft(d => ({ ...d, color: e.target.value }))}
                      className="w-8 h-6 rounded border border-border bg-card cursor-pointer" />
                    <code className="text-xs text-muted-foreground">{draft.color}</code>
                  </div>
                </div>
                <Palette className="w-4 h-4 text-muted-foreground self-start" />
              </div>
            </div>
            <div>
              <h3 className="text-sm font-semibold text-foreground mb-2">Plan</h3>
              <select value={draft.plan} onChange={e => setDraft(d => ({ ...d, plan: e.target.value }))}
                className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/40">
                {["Starter","Professional","Enterprise"].map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div>
              <h3 className="text-sm font-semibold text-foreground mb-2">Usage Limits</h3>
              <div className="space-y-2">
                {[{ label: "Users", used: selected.users, limit: selected.plan === "Enterprise" ? 50 : selected.plan === "Professional" ? 15 : 5 },
                  { label: "Clients", used: selected.clients, limit: selected.plan === "Enterprise" ? 200 : selected.plan === "Professional" ? 50 : 10 }].map(u => (
                  <div key={u.label}>
                    <div className="flex justify-between text-xs mb-1"><span className="text-muted-foreground">{u.label}</span><span className="text-foreground">{u.used}/{u.limit}</span></div>
                    <div className="w-full bg-muted rounded-full h-2">
                      <div className="bg-primary h-2 rounded-full" style={{ width: `${Math.min((u.used / u.limit) * 100, 100)}%` }} />
                    </div>
                  </div>
                ))}
              </div>
            </div>
            <div className="flex gap-2 pt-2">
              <Btn variant="primary" size="sm" onClick={saveTenant}>Save Changes</Btn>
              <Btn variant="danger" size="sm" onClick={() => { setTenants(prev => prev.map(x => x.id === selected.id ? { ...x, active: false } : x)); setSelected(null); toast.success("Tenant suspended"); }}>Suspend Tenant</Btn>
            </div>
          </div>
        )}
      </Modal>

      {/* Add Tenant modal */}
      <Modal open={showAddTenant} onClose={() => setShowAddTenant(false)} title="Add Tenant">
        <div className="space-y-3">
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1">Organization Name *</label>
            <input value={newTenant.name} onChange={e => setNewTenant(p => ({ ...p, name: e.target.value }))}
              placeholder="e.g. STIMES PRO — Dammam"
              className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/40" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1">Plan</label>
            <select value={newTenant.plan} onChange={e => setNewTenant(p => ({ ...p, plan: e.target.value }))}
              className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/40">
              {["Starter","Professional","Enterprise"].map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <Btn variant="ghost" size="sm" className="flex-1" onClick={() => setShowAddTenant(false)}>Cancel</Btn>
            <Btn variant="primary" size="sm" className="flex-1" onClick={() => {
              if (!newTenant.name.trim()) { toast.error("Organization name is required"); return; }
              const limit = newTenant.plan === "Enterprise" ? "50 GB" : newTenant.plan === "Professional" ? "20 GB" : "5 GB";
              setTenants(prev => [...prev, { id: `t${Date.now()}`, name: newTenant.name.trim(), plan: newTenant.plan, users: 1, clients: 0, storage: "0 GB", storageLimit: limit, active: true, since: "Today", logo: "🏢", color: "#7105ef" }]);
              toast.success("Tenant created");
              setShowAddTenant(false);
            }}>Create Tenant</Btn>
          </div>
        </div>
      </Modal>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// BUSINESS INTELLIGENCE DASHBOARD
// ─────────────────────────────────────────────────────────────
const BI_REVENUE_DATA = [
  { month: "Jul", revenue: 312000, target: 300000 }, { month: "Aug", revenue: 298000, target: 310000 },
  { month: "Sep", revenue: 376000, target: 340000 }, { month: "Oct", revenue: 341000, target: 350000 },
  { month: "Nov", revenue: 412000, target: 390000 }, { month: "Dec", revenue: 389000, target: 400000 },
  { month: "Jan", revenue: 427000, target: 420000 },
];

const BI_COMPLIANCE_DATA = [
  { name: "Valid", value: 187, color: "#10b981" },
  { name: "Expiring", value: 48, color: "#f59e0b" },
  { name: "Overdue", value: 24, color: "#ef4444" },
];

const BI_OFFICER_DATA = [
  { name: "Khalid", tasks: 42, renewals: 18, avg: 2.1 },
  { name: "Fatima", tasks: 38, renewals: 22, avg: 1.8 },
  { name: "Omar", tasks: 35, renewals: 15, avg: 2.4 },
];

const BI_CLIENT_GROWTH = [
  { month: "Aug", clients: 14 }, { month: "Sep", clients: 17 }, { month: "Oct", clients: 19 },
  { month: "Nov", clients: 22 }, { month: "Dec", clients: 24 }, { month: "Jan", clients: 27 },
];

function BIDashboardScreen({ invoices, complianceDocs, tasks }: { invoices: Invoice[]; complianceDocs: ComplianceDoc[]; tasks: Task[] }) {
  const [drillDown, setDrillDown] = useState<string | null>(null);

  // Derive live compliance donut from shared data
  const liveComplianceData = [
    { name: "Valid", value: complianceDocs.filter(d=>d.status==="valid").length, color: "#10b981" },
    { name: "Expiring", value: complianceDocs.filter(d=>d.status==="expiring").length, color: "#f59e0b" },
    { name: "Overdue", value: complianceDocs.filter(d=>d.status==="overdue").length, color: "#ef4444" },
  ];

  const livePaidRevenue = invoices.filter(i=>i.status==="paid").reduce((s,i)=>s+i.amount,0);
  const liveOutstanding = invoices.filter(i=>["pending","overdue"].includes(i.status)).reduce((s,i)=>s+i.amount,0);
  const liveTaskCompletion = tasks.length > 0 ? Math.round((tasks.filter(t=>t.status==="done").length / tasks.length) * 100) : 0;

  return (
    <div className="space-y-6">
      <PageHeader title="Business Intelligence" subtitle="Interactive analytics — click charts to drill down"
        actions={
          <div className="flex gap-2">
            <Btn variant="secondary" size="sm" onClick={() => exportCSV(BI_REVENUE_DATA.map(r => ({ Month: r.month, Revenue: r.revenue, Target: r.target })), "bi-revenue.csv")}>
              <Download className="w-3.5 h-3.5" />Export
            </Btn>
            <Btn variant="ghost" size="sm" onClick={() => toast.info("Scheduled report settings")}>
              <RefreshCw className="w-3.5 h-3.5" />Schedule
            </Btn>
          </div>
        }
      />

      {/* KPI summary row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: "Paid Revenue", value: `SAR ${(livePaidRevenue/1000).toFixed(0)}k`, delta: `${invoices.filter(i=>i.status==="paid").length} paid invoices`, icon: TrendUp, color: "text-primary", bg: "bg-accent", positive: true },
          { label: "Tasks Complete", value: `${liveTaskCompletion}%`, delta: `${tasks.filter(t=>t.status==="done").length}/${tasks.length} tasks`, icon: RefreshCw, color: "text-emerald-600", bg: "bg-green-50", positive: true },
          { label: "Docs Tracked", value: String(complianceDocs.length), delta: `${complianceDocs.filter(d=>d.status==="valid").length} valid`, icon: Timer, color: "text-blue-600", bg: "bg-blue-50", positive: true },
          { label: "Outstanding", value: `SAR ${(liveOutstanding/1000).toFixed(0)}k`, delta: `${invoices.filter(i=>i.status==="overdue").length} overdue`, icon: CreditCard, color: "text-amber-600", bg: "bg-amber-50", positive: true },
        ].map(k => (
          <div key={k.label} className="bg-card rounded-xl border border-border p-5">
            <div className="flex items-start justify-between mb-3">
              <div className={`w-10 h-10 rounded-lg ${k.bg} flex items-center justify-center`}>
                <k.icon className={`w-5 h-5 ${k.color}`} />
              </div>
              <span className="text-[10px] font-medium px-1.5 py-0.5 rounded-full bg-green-50 text-green-600">{k.delta}</span>
            </div>
            <p className="text-2xl font-bold text-foreground">{k.value}</p>
            <p className="text-xs text-muted-foreground mt-1">{k.label}</p>
          </div>
        ))}
      </div>

      {/* Revenue vs target + Compliance donut */}
      <div className="grid grid-cols-3 gap-4">
        <div className="col-span-2 bg-card rounded-xl border border-border p-5">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h3 className="text-sm font-semibold text-foreground">Revenue vs Target</h3>
              <p className="text-xs text-muted-foreground">Monthly billing — last 7 months</p>
            </div>
            {drillDown === "revenue" && (
              <button onClick={() => setDrillDown(null)} className="text-xs text-primary hover:underline flex items-center gap-1">
                <ChevronLeft className="w-3 h-3" />Back
              </button>
            )}
          </div>
          {/* Inline SVG grouped bar chart — avoids recharts duplicate-id issue */}
          {(() => {
            const w = 520, h = 200, pad = { t: 10, r: 10, b: 30, l: 40 };
            const innerW = w - pad.l - pad.r;
            const innerH = h - pad.t - pad.b;
            const maxV = Math.max(...BI_REVENUE_DATA.flatMap(d => [d.revenue, d.target]));
            const barW = (innerW / BI_REVENUE_DATA.length) * 0.35;
            const gap = barW * 0.3;
            return (
              <svg viewBox={`0 0 ${w} ${h}`} width="100%" height={220} style={{ cursor: "pointer" }} onClick={() => setDrillDown("revenue")}>
                {/* Y gridlines */}
                {[0,0.25,0.5,0.75,1].map(t => {
                  const y = pad.t + innerH * (1 - t);
                  return <line key={t} x1={pad.l} x2={pad.l + innerW} y1={y} y2={y} stroke="rgba(113,5,239,0.07)" strokeDasharray="3 3" />;
                })}
                {BI_REVENUE_DATA.map((d, i) => {
                  const slotW = innerW / BI_REVENUE_DATA.length;
                  const cx = pad.l + slotW * i + slotW / 2;
                  const revH = (d.revenue / maxV) * innerH;
                  const tarH = (d.target / maxV) * innerH;
                  return (
                    <g key={d.month}>
                      <rect x={cx - barW - gap / 2} y={pad.t + innerH - revH} width={barW} height={revH} fill="#7105ef" fillOpacity={0.85} rx={3} />
                      <rect x={cx + gap / 2} y={pad.t + innerH - tarH} width={barW} height={tarH} fill="#10b981" fillOpacity={0.4} rx={3} />
                      <text x={cx} y={h - 8} textAnchor="middle" fontSize={9} fill="#6b5b95">{d.month}</text>
                    </g>
                  );
                })}
                {[0,0.25,0.5,0.75,1].map(t => {
                  const v = maxV * t;
                  const y = pad.t + innerH * (1 - t);
                  return <text key={t} x={pad.l - 4} y={y + 3} textAnchor="end" fontSize={9} fill="#6b5b95">{`${(v/1000).toFixed(0)}k`}</text>;
                })}
              </svg>
            );
          })()}
          {drillDown === "revenue" && (
            <div className="mt-3 pt-3 border-t border-border">
              <p className="text-xs text-muted-foreground mb-2">Drill-down: Revenue by client (Jan 2025)</p>
              <div className="space-y-1.5">
                {[["TechVault Arabia","SAR 94,200"],["Global Tech LLC","SAR 78,500"],["AlFuturo Holdings","SAR 61,300"],["SkyBridge Corp","SAR 52,800"],["Meridian Services","SAR 18,200"]].map(([c, v]) => (
                  <div key={c} className="flex justify-between text-xs"><span className="text-foreground">{c}</span><span className="font-semibold text-foreground">{v}</span></div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="bg-card rounded-xl border border-border p-5">
          <h3 className="text-sm font-semibold text-foreground mb-1">Compliance Status</h3>
          <p className="text-xs text-muted-foreground mb-4">Total: {complianceDocs.length} documents</p>
          <ResponsiveContainer width="100%" height={160}>
            <RechartsPie>
              <Pie data={liveComplianceData} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={3} dataKey="value">
                {liveComplianceData.map((entry, i) => <Cell key={`cell-${i}`} fill={entry.color} />)}
              </Pie>
              <Tooltip contentStyle={{ background: "#fff", border: "1px solid rgba(113,5,239,0.12)", borderRadius: 8, fontSize: 11 }} />
            </RechartsPie>
          </ResponsiveContainer>
          <div className="space-y-1.5 mt-2">
            {liveComplianceData.map(d => (
              <div key={d.name} className="flex items-center justify-between text-xs">
                <div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: d.color }} /><span className="text-muted-foreground">{d.name}</span></div>
                <span className="font-semibold text-foreground">{d.value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Officer performance + Client growth */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-card rounded-xl border border-border p-5">
          <h3 className="text-sm font-semibold text-foreground mb-4">Officer Performance</h3>
          {/* Inline horizontal bar chart */}
          {(() => {
            const maxV = Math.max(...BI_OFFICER_DATA.flatMap(d => [d.tasks, d.renewals]));
            const rowH = 32, labelW = 50, barAreaW = 220, gap = 4;
            const bH = 10;
            return (
              <svg width="100%" viewBox={`0 0 ${labelW + barAreaW + 20} ${BI_OFFICER_DATA.length * rowH + 10}`} style={{ overflow: "visible" }}>
                {BI_OFFICER_DATA.map((d, i) => {
                  const y = i * rowH + 10;
                  const tasksW = (d.tasks / maxV) * barAreaW;
                  const renewalsW = (d.renewals / maxV) * barAreaW;
                  return (
                    <g key={d.name}>
                      <text x={labelW - 6} y={y + bH} textAnchor="end" fontSize={9} fill="#6b5b95">{d.name}</text>
                      <rect x={labelW} y={y} width={tasksW} height={bH} fill="#7105ef" fillOpacity={0.8} rx={2} />
                      <rect x={labelW} y={y + bH + gap} width={renewalsW} height={bH} fill="#10b981" fillOpacity={0.7} rx={2} />
                    </g>
                  );
                })}
              </svg>
            );
          })()}
          <div className="flex items-center gap-4 mt-3 pt-3 border-t border-border text-xs text-muted-foreground">
            <div className="flex items-center gap-2"><span className="w-3 h-0.5 bg-primary rounded" />Tasks</div>
            <div className="flex items-center gap-2"><span className="w-3 h-0.5 bg-emerald-500 rounded" />Renewals</div>
          </div>
        </div>

        <div className="bg-card rounded-xl border border-border p-5">
          <h3 className="text-sm font-semibold text-foreground mb-4">Client Growth</h3>
          {(() => {
            const w = 260, h = 160, pad = { t: 8, r: 8, b: 24, l: 28 };
            const innerW = w - pad.l - pad.r, innerH = h - pad.t - pad.b;
            const minV = 10, maxV = 30;
            const barW = (innerW / BI_CLIENT_GROWTH.length) * 0.5;
            return (
              <svg viewBox={`0 0 ${w} ${h}`} width="100%" height={160}>
                {[10,15,20,25,30].map(v => {
                  const y = pad.t + innerH - ((v - minV) / (maxV - minV)) * innerH;
                  return <line key={v} x1={pad.l} x2={pad.l + innerW} y1={y} y2={y} stroke="rgba(113,5,239,0.07)" strokeDasharray="3 3" />;
                })}
                {BI_CLIENT_GROWTH.map((d, i) => {
                  const slotW = innerW / BI_CLIENT_GROWTH.length;
                  const x = pad.l + slotW * i + slotW / 2 - barW / 2;
                  const bH = ((d.clients - minV) / (maxV - minV)) * innerH;
                  return (
                    <g key={d.month}>
                      <rect x={x} y={pad.t + innerH - bH} width={barW} height={bH} fill="#7105ef" fillOpacity={0.8} rx={3} />
                      <text x={x + barW / 2} y={h - 6} textAnchor="middle" fontSize={9} fill="#6b5b95">{d.month}</text>
                    </g>
                  );
                })}
              </svg>
            );
          })()}
          <div className="flex items-center justify-between mt-3 pt-3 border-t border-border">
            <span className="text-xs text-muted-foreground">+13 new clients in 6 months</span>
            <span className="text-xs font-semibold text-emerald-600">+93% growth</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// KPI BUILDER SCREEN
// ─────────────────────────────────────────────────────────────
const KPI_METRICS = [
  "Total Revenue (MTD)", "Overdue Documents", "Active Tasks", "Compliance Score",
  "Renewals Processed", "Invoice Collection Rate", "Avg. SLA Days", "New Clients",
  "Open Approvals", "Documents Expiring ≤30d", "Task Completion Rate", "Breached SLAs",
];

interface CustomKPI { id: string; metric: string; range: string; viz: "number" | "bar" | "trend"; color: string; }

function KPIBuilderScreen() {
  const [kpis, setKpis] = useState<CustomKPI[]>([
    { id: "ck1", metric: "Overdue Documents", range: "This Month", viz: "number", color: "#ef4444" },
    { id: "ck2", metric: "Renewals Processed", range: "Last 30 Days", viz: "trend", color: "#10b981" },
    { id: "ck3", metric: "Invoice Collection Rate", range: "This Quarter", viz: "bar", color: "#7105ef" },
  ]);
  const [showBuilder, setShowBuilder] = useState(false);
  const [newMetric, setNewMetric] = useState(KPI_METRICS[0]);
  const [newRange, setNewRange] = useState("This Month");
  const [newViz, setNewViz] = useState<CustomKPI["viz"]>("number");
  const [newColor, setNewColor] = useState("#7105ef");

  const addKPI = () => {
    const kpi: CustomKPI = { id: `ck${Date.now()}`, metric: newMetric, range: newRange, viz: newViz, color: newColor };
    setKpis(prev => [...prev, kpi]);
    setShowBuilder(false);
    toast.success(`KPI "${newMetric}" added to dashboard`);
  };

  const KPI_MOCK_VALUES: Record<string, string> = {
    "Total Revenue (MTD)": "SAR 427K", "Overdue Documents": "24", "Active Tasks": "31",
    "Compliance Score": "82%", "Renewals Processed": "1,247", "Invoice Collection Rate": "91%",
    "Avg. SLA Days": "8.4d", "New Clients": "3", "Open Approvals": "5",
    "Documents Expiring ≤30d": "48", "Task Completion Rate": "78%", "Breached SLAs": "2",
  };

  const vizColors = ["#7105ef","#10b981","#ef4444","#f59e0b","#3b82f6","#8b5cf6"];

  return (
    <div>
      <PageHeader title="KPI Builder" subtitle="Create custom KPI cards to pin to your dashboard"
        actions={<Btn variant="primary" size="sm" onClick={() => setShowBuilder(true)}><Plus className="w-3.5 h-3.5" />New KPI Card</Btn>}
      />

      {/* Existing KPI cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 mb-6">
        {kpis.map(k => (
          <div key={k.id} className="bg-card rounded-xl border border-border p-5 relative group">
            <button onClick={() => { setKpis(prev => prev.filter(x => x.id !== k.id)); toast.success("KPI removed"); }}
              className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity p-1 rounded hover:bg-muted text-muted-foreground">
              <X className="w-3.5 h-3.5" />
            </button>
            <div className="flex items-center gap-2 mb-3">
              <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: k.color }} />
              <span className="text-xs text-muted-foreground font-medium">{k.range}</span>
              <span className="text-[10px] bg-muted px-1.5 py-0.5 rounded text-muted-foreground ml-auto">{k.viz}</span>
            </div>
            <p className="text-xs text-muted-foreground mb-1">{k.metric}</p>
            {k.viz === "number" && <p className="text-3xl font-bold" style={{ color: k.color }}>{KPI_MOCK_VALUES[k.metric] || "—"}</p>}
            {k.viz === "trend" && (
              <div>
                <p className="text-3xl font-bold mb-2" style={{ color: k.color }}>{KPI_MOCK_VALUES[k.metric] || "—"}</p>
                <div className="h-10 flex items-end gap-1">
                  {[60,75,55,80,70,90,85,95].map((h, i) => (
                    <div key={i} className="flex-1 rounded-sm" style={{ height: `${h}%`, backgroundColor: k.color + "60" }} />
                  ))}
                </div>
              </div>
            )}
            {k.viz === "bar" && (
              <div>
                <p className="text-3xl font-bold mb-2" style={{ color: k.color }}>{KPI_MOCK_VALUES[k.metric] || "—"}</p>
                <div className="w-full bg-muted rounded-full h-2">
                  <div className="h-2 rounded-full" style={{ width: "91%", backgroundColor: k.color }} />
                </div>
                <p className="text-xs text-muted-foreground mt-1">91 of 100 target</p>
              </div>
            )}
            <div className="mt-3 pt-3 border-t border-border flex items-center justify-between">
              <span className="text-xs text-muted-foreground">Pinned to Dashboard</span>
              <Btn variant="ghost" size="xs" onClick={() => { setKpis(prev => [...prev, { ...k, id: `ck${Date.now()}` }]); toast.success("KPI card duplicated to dashboard"); }}>
                <Copy className="w-3 h-3" />Duplicate
              </Btn>
            </div>
          </div>
        ))}

        {/* Add new card placeholder */}
        <button onClick={() => setShowBuilder(true)}
          className="bg-muted/30 rounded-xl border-2 border-dashed border-border p-5 hover:border-primary/40 hover:bg-accent/20 transition-all flex flex-col items-center justify-center gap-2 text-muted-foreground hover:text-primary min-h-[140px]">
          <PlusCircle className="w-6 h-6" />
          <span className="text-sm font-medium">Add KPI Card</span>
        </button>
      </div>

      {/* Builder panel */}
      <Modal open={showBuilder} onClose={() => setShowBuilder(false)} title="Build New KPI Card">
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1.5">Metric</label>
            <select value={newMetric} onChange={e => setNewMetric(e.target.value)}
              className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/50">
              {KPI_METRICS.map(m => <option key={m}>{m}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1.5">Date Range</label>
            <select value={newRange} onChange={e => setNewRange(e.target.value)}
              className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/50">
              {["Today","This Week","This Month","Last 30 Days","This Quarter","YTD"].map(r => <option key={r}>{r}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1.5">Visualization</label>
            <div className="grid grid-cols-3 gap-2">
              {(["number","trend","bar"] as const).map(v => (
                <button key={v} onClick={() => setNewViz(v)}
                  className={`px-3 py-2.5 rounded-lg border text-sm font-medium capitalize transition-colors ${newViz === v ? "border-primary bg-accent text-primary" : "border-border bg-muted text-muted-foreground hover:border-primary/40"}`}>
                  {v === "number" ? "📊 Number" : v === "trend" ? "📈 Trend" : "📉 Bar"}
                </button>
              ))}
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1.5">Color</label>
            <div className="flex gap-2">
              {vizColors.map(c => (
                <button key={c} onClick={() => setNewColor(c)}
                  className={`w-8 h-8 rounded-lg transition-transform hover:scale-110 ${newColor === c ? "ring-2 ring-offset-2 ring-foreground" : ""}`}
                  style={{ backgroundColor: c }} />
              ))}
            </div>
          </div>
          <div className="bg-muted rounded-xl p-4">
            <p className="text-xs text-muted-foreground mb-1">Preview</p>
            <p className="text-xs font-medium text-muted-foreground mb-1">{newMetric}</p>
            <p className="text-2xl font-bold" style={{ color: newColor }}>{KPI_MOCK_VALUES[newMetric] || "—"}</p>
            <p className="text-xs text-muted-foreground mt-1">{newRange} · {newViz}</p>
          </div>
          <div className="flex gap-2 pt-2">
            <Btn variant="primary" size="sm" onClick={addKPI} className="flex-1">Add to Dashboard</Btn>
            <Btn variant="ghost" size="sm" onClick={() => setShowBuilder(false)}>Cancel</Btn>
          </div>
        </div>
      </Modal>
    </div>
  );
}

