// Real, no-code Form Builder — define extra fields for any entity (Employee, Client, …). Fields render on that entity's form.
// Form Builder: create several standalone forms (like Object Builder) with your own fields + submissions. No tabs.
function FormBuilderScreen() {
  return <ObjectBuilderScreen kind="form" noun="Form" title="Form Builder" subtitle="Create several forms with your own fields — e.g. Onboarding, Service Request — then collect and track submissions." recordsLabel="submissions" defaultIcon="📝" />;
}
// Custom fields for built-in records (Employee, Client) — appear on their Add forms.
function RecordFieldsBuilder() {
  const [entity, setEntity] = useState<string>("employee");
  const [allFields, setAllFields] = useState<CustomFieldDef[]>(CUSTOM_FIELDS);
  useEffect(() => { (async () => { try { const d = await api.get("/api/custom-fields"); if (Array.isArray(d)) { setAllFields(d); setCustomFieldsCatalog(d); } } catch { /* keep cached */ } })(); }, []);
  const sync = (list: CustomFieldDef[]) => { setAllFields(list); setCustomFieldsCatalog(list); };
  const entityFields = allFields.filter(f => f.entity === entity).sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));
  const entityLabel = FORM_ENTITIES.find(e => e.id === entity)?.label ?? entity;
  const standardNote: Record<string, string> = { employee: "Full Name · Role · Documents — always captured.", client: "Company Name · CR · Industry · City · Contact · Email · Phone — always captured." };
  const [showField, setShowField] = useState(false);
  const [editing, setEditing] = useState<CustomFieldDef | null>(null);
  const blank = (): CustomFieldDef => ({ id: "", entity, label: "", type: "text", options: [], required: false, sortOrder: 0 });
  const [fForm, setFForm] = useState<CustomFieldDef>(blank());
  const [optsText, setOptsText] = useState("");
  const openNew = () => { setEditing(null); setFForm(blank()); setOptsText(""); setShowField(true); };
  const openEdit = (f: CustomFieldDef) => { setEditing(f); setFForm({ ...f }); setOptsText((f.options ?? []).join(", ")); setShowField(true); };
  const saveField = async () => {
    if (!fForm.label.trim()) { toast.error("Field label is required"); return; }
    const options = fForm.type === "dropdown" ? optsText.split(",").map(s => s.trim()).filter(Boolean) : undefined;
    if (fForm.type === "dropdown" && (!options || options.length === 0)) { toast.error("Add at least one dropdown option"); return; }
    if (editing) {
      const upd: CustomFieldDef = { ...fForm, options };
      try { await api.put(`/api/custom-fields/${editing.id}`, { label: upd.label, type: upd.type, options: options ?? null, required: !!upd.required, sortOrder: upd.sortOrder ?? 0 }); } catch { toast.error("Server unreachable — saved locally only"); }
      sync(allFields.map(x => x.id === editing.id ? upd : x));
      toast.success("Field updated");
    } else {
      const id = `cf${Date.now()}`;
      const created: CustomFieldDef = { ...fForm, id, entity, sortOrder: entityFields.length, options };
      try { const res = await api.post("/api/custom-fields", { id, entity, label: created.label, type: created.type, options: options ?? null, required: !!created.required, sortOrder: created.sortOrder }); if (res?.id) created.id = res.id; } catch { toast.error("Server unreachable — saved locally only"); }
      sync([...allFields, created]);
      toast.success("Field added");
    }
    setShowField(false);
  };
  const removeField = async (f: CustomFieldDef) => {
    try { await api.del(`/api/custom-fields/${f.id}`); } catch { /* removed locally */ }
    sync(allFields.filter(x => x.id !== f.id));
    toast.success("Field removed");
  };
  return (
    <div>
      <PageHeader title="Form Builder" subtitle="Define extra fields captured on a record's form. Pick an entity, then add its fields — they appear automatically on that form."
        actions={<Btn variant="primary" size="sm" onClick={openNew}><Plus className="w-3.5 h-3.5" />Add Field</Btn>} />
      {/* Entity selector — the Form Builder works for any entity, not just employees */}
      <div className="flex items-center gap-1 bg-muted rounded-lg p-1 mb-4 w-fit">
        {FORM_ENTITIES.map(e => (
          <button key={e.id} onClick={() => setEntity(e.id)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${entity === e.id ? "bg-card text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"}`}>
            {e.label}{" "}<span className="text-[10px] text-muted-foreground">({allFields.filter(f => f.entity === e.id).length})</span>
          </button>
        ))}
      </div>
      <div className="bg-card rounded-xl border border-border overflow-hidden mb-4">
        <div className="p-4 border-b border-border"><p className="text-sm font-semibold text-foreground">{entityLabel} — standard fields</p><p className="text-[11px] text-muted-foreground mt-0.5">{standardNote[entity] ?? "Built-in fields — always captured."}</p></div>
        {entityFields.length === 0 ? (
          <div className="p-4"><EmptyState icon={FormInput} title={`No custom ${entityLabel.toLowerCase()} fields yet`} message={`Add fields — they'll appear on the Add ${entityLabel} form automatically.`} action={<Btn variant="primary" size="sm" onClick={openNew}><Plus className="w-3.5 h-3.5" />Add Field</Btn>} /></div>
        ) : (
          <div className="divide-y divide-border">
            {entityFields.map(f => (
              <div key={f.id} className="flex items-center gap-3 px-4 py-3 hover:bg-muted/30 transition-colors">
                <span className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0"><FormInput className="w-4 h-4 text-primary" /></span>
                <div className="flex-1 min-w-0"><p className="text-sm font-medium text-foreground">{f.label}{f.required && <span className="text-red-500 ml-1">*</span>}</p><p className="text-[11px] text-muted-foreground capitalize">{f.type}{f.type === "dropdown" && f.options?.length ? ` · ${f.options.join(", ")}` : ""}</p></div>
                <button onClick={() => openEdit(f)} className="p-1.5 rounded hover:bg-muted text-muted-foreground" title="Edit"><Pencil className="w-3.5 h-3.5" /></button>
                <button onClick={() => removeField(f)} className="p-1.5 rounded hover:bg-red-50 hover:text-red-500 text-muted-foreground" title="Remove"><Trash2 className="w-3.5 h-3.5" /></button>
              </div>
            ))}
          </div>
        )}
      </div>
      <Modal open={showField} onClose={() => setShowField(false)} title={editing ? "Edit field" : `Add ${entityLabel.toLowerCase()} field`}>
        <div className="space-y-3">
          <div><label className="block text-xs font-medium text-foreground mb-1">Field label *</label>
            <input value={fForm.label} autoFocus onChange={e => setFForm(f => ({ ...f, label: e.target.value }))} placeholder="e.g. Nationality" className="w-full px-3 py-2 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50" /></div>
          <div className="grid grid-cols-2 gap-3">
            <div><label className="block text-xs font-medium text-foreground mb-1">Type</label>
              <select value={fForm.type} onChange={e => setFForm(f => ({ ...f, type: e.target.value as CustomFieldDef["type"] }))} className="w-full px-3 py-2 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50">
                <option value="text">Text</option><option value="number">Number</option><option value="date">Date</option><option value="dropdown">Dropdown</option>
              </select></div>
            <label className="flex items-end gap-2 text-sm text-foreground cursor-pointer pb-2"><input type="checkbox" checked={!!fForm.required} onChange={e => setFForm(f => ({ ...f, required: e.target.checked }))} />Required</label>
          </div>
          {fForm.type === "dropdown" && (
            <div><label className="block text-xs font-medium text-foreground mb-1">Options (comma-separated)</label>
              <input value={optsText} onChange={e => setOptsText(e.target.value)} placeholder="e.g. Saudi, Indian, Filipino" className="w-full px-3 py-2 text-sm border border-border rounded-lg bg-muted focus:outline-none focus:ring-2 focus:ring-ring/50" /></div>
          )}
          <div className="flex gap-3 pt-1"><Btn variant="primary" className="flex-1 justify-center" onClick={saveField}>{editing ? "Save field" : "Add field"}</Btn><Btn variant="secondary" onClick={() => setShowField(false)}>Cancel</Btn></div>
        </div>
      </Modal>
    </div>
  );
}

function FormBuilderScreenLegacy() {
  const [forms, setForms] = useState<BuiltForm[]>(INIT_FORMS);
  const [selectedForm, setSelectedForm] = useState<BuiltForm>(INIT_FORMS[0]);
  const [preview, setPreview] = useState(false);
  const [showNewForm, setShowNewForm] = useState(false);
  const [newFormName, setNewFormName] = useState("");
  const [newFormDesc, setNewFormDesc] = useState("");
  const [addingField, setAddingField] = useState(false);
  const [newFLabel, setNewFLabel] = useState("");
  const [newFType, setNewFType] = useState<FieldType>("text");
  const [newFReq, setNewFReq] = useState(false);

  const current = forms.find(f => f.id === selectedForm.id) || selectedForm;

  const addField = () => {
    if (!newFLabel.trim()) return;
    const field: FormField = { id: `ff${Date.now()}`, label: newFLabel, type: newFType, required: newFReq };
    setForms(prev => prev.map(f => f.id === current.id ? { ...f, fields: [...f.fields, field] } : f));
    setNewFLabel(""); setNewFType("text"); setNewFReq(false); setAddingField(false);
    toast.success("Field added");
  };

  const moveField = (fieldId: string, dir: "up" | "down") => {
    setForms(prev => prev.map(f => {
      if (f.id !== current.id) return f;
      const idx = f.fields.findIndex(x => x.id === fieldId);
      if ((dir === "up" && idx === 0) || (dir === "down" && idx === f.fields.length - 1)) return f;
      const newFields = [...f.fields];
      const swap = dir === "up" ? idx - 1 : idx + 1;
      [newFields[idx], newFields[swap]] = [newFields[swap], newFields[idx]];
      return { ...f, fields: newFields };
    }));
  };

  const removeField = (fieldId: string) => {
    setForms(prev => prev.map(f => f.id !== current.id ? f : { ...f, fields: f.fields.filter(x => x.id !== fieldId) }));
  };

  return (
    <div>
      <PageHeader title="Form Builder" subtitle="Compose intake forms from typed fields — use in workflows and the client portal"
        actions={
          <div className="flex gap-2">
            <Btn variant="secondary" size="sm" onClick={() => setPreview(!preview)}>
              <Eye className="w-3.5 h-3.5" />{preview ? "Edit" : "Preview"}
            </Btn>
            <Btn variant="primary" size="sm" onClick={() => setShowNewForm(true)}><Plus className="w-3.5 h-3.5" />New Form</Btn>
          </div>
        }
      />
      <div className="flex gap-5">
        {/* Form list */}
        <div className="w-52 flex-shrink-0 space-y-1">
          {forms.map(f => (
            <button key={f.id} onClick={() => { setSelectedForm(f); setPreview(false); }}
              className={`w-full text-left px-3 py-3 rounded-xl border transition-all ${current.id === f.id ? "border-primary bg-accent" : "border-border bg-card hover:bg-muted"}`}>
              <p className={`text-sm font-medium ${current.id === f.id ? "text-foreground" : "text-muted-foreground"}`}>{f.name}</p>
              <p className="text-[10px] text-muted-foreground mt-0.5">{f.fields.length} fields</p>
            </button>
          ))}
          <button onClick={() => setShowNewForm(true)}
            className="w-full flex items-center gap-2 px-3 py-2.5 rounded-xl border-2 border-dashed border-border text-muted-foreground hover:border-primary hover:text-primary transition-colors">
            <Plus className="w-3.5 h-3.5" /><span className="text-xs font-medium">New Form</span>
          </button>
        </div>

        <div className="flex-1">
          {preview ? (
            /* Preview mode */
            <div className="bg-card rounded-xl border border-border p-6 max-w-lg mx-auto">
              <div className="mb-6">
                <h2 className="text-lg font-bold text-foreground">{current.name}</h2>
                <p className="text-sm text-muted-foreground mt-0.5">{current.description}</p>
              </div>
              <div className="space-y-4">
                {current.fields.map(field => {
                  const meta = FIELD_TYPE_META[field.type];
                  const Icon = meta.icon;
                  return (
                    <div key={field.id}>
                      <label className="block text-sm font-medium text-foreground mb-1.5">
                        {field.label}{field.required && <span className="text-red-500 ml-1">*</span>}
                      </label>
                      {field.type === "text" && <input disabled placeholder={field.placeholder || "Type here…"} className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg" />}
                      {field.type === "number" && <input type="number" disabled placeholder="0" className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg" />}
                      {field.type === "date" && <input type="date" disabled className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg" />}
                      {field.type === "dropdown" && (
                        <select disabled className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg">
                          <option>Select…</option>
                          {field.options?.map(o => <option key={o}>{o}</option>)}
                        </select>
                      )}
                      {field.type === "file" && <div className="flex items-center gap-2 px-3 py-2 bg-muted border border-dashed border-border rounded-lg text-sm text-muted-foreground"><FileUp className="w-4 h-4" />Click to upload</div>}
                      {field.type === "gps" && <div className="flex items-center gap-2 px-3 py-2 bg-muted border border-border rounded-lg text-sm text-muted-foreground"><MapPinIcon className="w-4 h-4" />Capture location</div>}
                      {field.type === "signature" && <div className="h-20 bg-muted border border-dashed border-border rounded-lg flex items-center justify-center text-sm text-muted-foreground"><PenSquare className="w-4 h-4 mr-2" />Sign here</div>}
                      {field.type === "boolean" && <div className="flex items-center gap-2"><div className="w-10 h-5 rounded-full bg-gray-200"><div className="w-4 h-4 rounded-full bg-white shadow m-0.5" /></div><span className="text-sm text-muted-foreground">No</span></div>}
                    </div>
                  );
                })}
                <Btn variant="primary" size="md" className="w-full mt-2" onClick={() => toast.success("Form submitted (preview mode)")}>Submit</Btn>
              </div>
            </div>
          ) : (
            /* Edit mode */
            <div className="bg-card rounded-xl border border-border p-5">
              <div className="flex items-start justify-between mb-5">
                <div>
                  <h2 className="text-base font-bold text-foreground">{current.name}</h2>
                  <p className="text-sm text-muted-foreground">{current.description}</p>
                </div>
                <Btn variant="ghost" size="sm" onClick={() => toast.info("Form settings")}><Settings className="w-3.5 h-3.5" />Settings</Btn>
              </div>
              <div className="space-y-2 mb-4">
                {current.fields.map((field, idx) => {
                  const meta = FIELD_TYPE_META[field.type];
                  const Icon = meta.icon;
                  return (
                    <div key={field.id} className="flex items-center gap-3 p-3 bg-muted rounded-xl group">
                      <GripVertical className="w-4 h-4 text-muted-foreground opacity-40 cursor-grab" />
                      <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-xs font-medium flex-shrink-0 ${meta.color}`}>
                        <Icon className="w-3 h-3" />{meta.label}
                      </span>
                      <span className="text-sm font-medium text-foreground flex-1">{field.label}</span>
                      {field.required && <span className="text-[10px] text-red-500 font-bold uppercase">Req</span>}
                      <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => moveField(field.id, "up")} className="p-1 rounded hover:bg-card text-muted-foreground"><ArrowUp className="w-3 h-3" /></button>
                        <button onClick={() => moveField(field.id, "down")} className="p-1 rounded hover:bg-card text-muted-foreground"><ArrowDown className="w-3 h-3" /></button>
                        <button onClick={() => removeField(field.id)} className="p-1 rounded hover:bg-destructive/10 text-muted-foreground hover:text-destructive"><X className="w-3.5 h-3.5" /></button>
                      </div>
                    </div>
                  );
                })}
              </div>
              {addingField ? (
                <div className="p-4 border border-primary/30 rounded-xl bg-accent/30 space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                    <input value={newFLabel} onChange={e => setNewFLabel(e.target.value)} placeholder="Field label…" autoFocus
                      className="px-3 py-2 text-sm bg-card border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/50" />
                    <select value={newFType} onChange={e => setNewFType(e.target.value as FieldType)}
                      className="px-3 py-2 text-sm bg-card border border-border rounded-lg focus:outline-none">
                      {(Object.keys(FIELD_TYPE_META) as FieldType[]).map(t => <option key={t} value={t}>{FIELD_TYPE_META[t].label}</option>)}
                    </select>
                  </div>
                  <div className="flex items-center gap-3">
                    <label className="flex items-center gap-2 text-xs cursor-pointer"><input type="checkbox" checked={newFReq} onChange={e => setNewFReq(e.target.checked)} className="accent-primary" />Required</label>
                    <div className="flex gap-2 ml-auto">
                      <Btn variant="primary" size="sm" onClick={addField}>Add</Btn>
                      <Btn variant="ghost" size="sm" onClick={() => setAddingField(false)}>Cancel</Btn>
                    </div>
                  </div>
                </div>
              ) : (
                <button onClick={() => setAddingField(true)}
                  className="w-full flex items-center justify-center gap-2 py-2.5 border-2 border-dashed border-border rounded-xl text-xs font-medium text-muted-foreground hover:border-primary hover:text-primary transition-colors">
                  <Plus className="w-3.5 h-3.5" />Add Field
                </button>
              )}
              <div className="flex gap-2 mt-4 pt-4 border-t border-border">
                <Btn variant="secondary" size="sm" onClick={() => toast.success(`"${current.name}" saved — ${current.fields.length} field(s)`)}>Save Form</Btn>
                <Btn variant="ghost" size="sm" onClick={() => toast.info("Publish to client portal")}>Publish to Portal</Btn>
              </div>
            </div>
          )}
        </div>
      </div>

      <Modal open={showNewForm} onClose={() => setShowNewForm(false)} title="New Form">
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1.5">Form Name</label>
            <input value={newFormName} onChange={e => setNewFormName(e.target.value)} placeholder="e.g. Visa Application Intake"
              className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-ring/50" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1.5">Description</label>
            <input value={newFormDesc} onChange={e => setNewFormDesc(e.target.value)} placeholder="Brief description of this form's purpose"
              className="w-full px-3 py-2 text-sm bg-muted border border-border rounded-lg focus:outline-none" />
          </div>
          <div className="flex gap-2 pt-2">
            <Btn variant="primary" size="sm" className="flex-1" onClick={() => {
              if (!newFormName.trim()) return;
              const f: BuiltForm = { id: `form${Date.now()}`, name: newFormName, description: newFormDesc, fields: [] };
              setForms(prev => [...prev, f]); setSelectedForm(f);
              setNewFormName(""); setNewFormDesc(""); setShowNewForm(false);
              toast.success("Form created");
            }}>Create Form</Btn>
            <Btn variant="ghost" size="sm" onClick={() => setShowNewForm(false)}>Cancel</Btn>
          </div>
        </div>
      </Modal>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// WORKFLOW BUILDER
// ─────────────────────────────────────────────────────────────
type StepType = "notify" | "create_task" | "request_approval" | "draft_invoice" | "assign_officer" | "create_project" | "complete";
type RunStatus = "success" | "running" | "failed" | "pending";

interface WorkflowStep {
  id: string; type: StepType; label: string; config: string;
  runStatus?: RunStatus; runTime?: string;
}

interface WorkflowDef {
  id: string; name: string; trigger: string; active: boolean; steps: WorkflowStep[];
  lastRun?: string; runCount: number;
}

const STEP_META: Record<StepType, { label: string; icon: React.ElementType; color: string; bg: string }> = {
  notify: { label: "Notify", icon: BellIcon, color: "text-blue-700", bg: "bg-blue-50" },
  create_task: { label: "Create Task", icon: ClipboardList, color: "text-purple-700", bg: "bg-purple-50" },
  request_approval: { label: "Request Approval", icon: ThumbsUp, color: "text-amber-700", bg: "bg-amber-50" },
  draft_invoice: { label: "Draft Invoice", icon: Receipt, color: "text-green-700", bg: "bg-green-50" },
  assign_officer: { label: "Assign Officer", icon: UsersIcon, color: "text-indigo-700", bg: "bg-indigo-50" },
  create_project: { label: "Create Project", icon: Layers, color: "text-violet-700", bg: "bg-violet-50" },
  complete: { label: "Complete", icon: BadgeCheck, color: "text-emerald-700", bg: "bg-emerald-50" },
};

