function NotificationEngineScreen() {
  const [rules, setRules] = useState(NOTIF_RULES);
  const [feed, setFeed] = useState(NOTIF_FEED);
  const [tab, setTab] = useState<"settings" | "center">("settings");

  const toggleChannel = (ruleId: string, ch: NotifChannel) => {
    setRules(prev => prev.map(r => {
      if (r.id !== ruleId) return r;
      const has = r.channels.includes(ch);
      return { ...r, channels: has ? r.channels.filter(c => c !== ch) : [...r.channels, ch] };
    }));
  };

  const removeLeadDay = (ruleId: string, day: number) => {
    setRules(prev => prev.map(r => r.id !== ruleId ? r : { ...r, defaultLeadDays: r.defaultLeadDays.filter(d => d !== day) }));
  };

  const addLeadDay = (ruleId: string, day: number) => {
    if (isNaN(day) || day < 0) return;
    setRules(prev => prev.map(r => r.id !== ruleId ? r : { ...r, defaultLeadDays: [...new Set([...r.defaultLeadDays, day])].sort((a, b) => b - a) }));
  };

  const markAllRead = () => setFeed(prev => prev.map(n => ({ ...n, read: true })));

  return (
    <div>
      <PageHeader title="Notification Engine" subtitle="Configure lead times, channels, provider status and the notification center feed" />

      {/* Tab selector */}
      <div className="flex items-center gap-2 mb-6">
        <div className="flex items-center bg-muted rounded-lg p-1">
          {([["settings","⚙️ Notification Settings"], ["center","🔔 Notification Center"]] as const).map(([v, label]) => (
            <button key={v} onClick={() => setTab(v)}
              className={`px-4 py-1.5 text-xs font-medium rounded-md transition-colors ${tab === v ? "bg-card text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"}`}>
              {label}
            </button>
          ))}
        </div>
        {tab === "center" && (
          <button onClick={markAllRead} className="ml-auto text-xs text-primary hover:underline">Mark all read</button>
        )}
      </div>

      {tab === "settings" ? (
        <div className="space-y-5">
          {/* Provider status */}
          <div className="bg-card rounded-xl border border-border p-5">
            <h3 className="text-sm font-semibold text-foreground mb-4">Connected Providers</h3>
            <div className="grid grid-cols-4 gap-3">
              {(Object.entries(CHANNEL_META) as [NotifChannel, typeof CHANNEL_META[NotifChannel]][]).map(([ch, meta]) => (
                <div key={ch} className={`flex items-center justify-between p-3 rounded-xl border ${meta.color}`}>
                  <div className="flex items-center gap-2">
                    <span className="text-lg">{meta.icon}</span>
                    <div>
                      <p className="text-xs font-semibold">{meta.label}</p>
                      <p className={`text-[10px] font-medium ${meta.connected ? "text-emerald-600" : "text-red-500"}`}>
                        {meta.connected ? "Connected" : "Not connected"}
                      </p>
                    </div>
                  </div>
                  <Btn variant="ghost" size="xs" onClick={() => toast.info(meta.connected ? `Test ${meta.label} sent` : `Connect ${meta.label} provider`)}>
                    {meta.connected ? "Test" : "Connect"}
                  </Btn>
                </div>
              ))}
            </div>
          </div>

          {/* Notification rules */}
          <div className="bg-card rounded-xl border border-border overflow-hidden">
            <div className="px-5 py-4 border-b border-border bg-muted/30">
              <h3 className="text-sm font-semibold text-foreground">Notification Rules</h3>
              <p className="text-xs text-muted-foreground mt-0.5">Set lead-time chips and enabled channels per event type</p>
            </div>
            <div className="divide-y divide-border">
              {rules.map(rule => (
                <div key={rule.id} className="px-5 py-4">
                  <div className="flex items-start gap-4">
                    <div className="flex-1">
                      <p className="text-sm font-semibold text-foreground mb-2">{rule.event}</p>
                      {/* Lead days */}
                      <div className="flex items-center gap-2 flex-wrap mb-2">
                        <span className="text-xs text-muted-foreground">Lead time:</span>
                        {rule.defaultLeadDays.map(day => (
                          <div key={day} className="flex items-center gap-1 bg-accent px-2.5 py-1 rounded-full">
                            <span className="text-xs font-medium text-primary">{day === 0 ? "Same day" : `${day}d`}</span>
                            <button onClick={() => removeLeadDay(rule.id, day)} className="text-primary/60 hover:text-primary"><X className="w-2.5 h-2.5" /></button>
                          </div>
                        ))}
                        <AddDayChip onAdd={day => addLeadDay(rule.id, day)} />
                      </div>
                    </div>
                    {/* Channels */}
                    <div className="flex items-center gap-2 flex-shrink-0">
                      {(Object.keys(CHANNEL_META) as NotifChannel[]).map(ch => {
                        const meta = CHANNEL_META[ch];
                        const active = rule.channels.includes(ch);
                        return (
                          <button key={ch} onClick={() => toggleChannel(rule.id, ch)}
                            className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border text-xs font-medium transition-all ${active ? `${meta.color} border-current` : "bg-muted text-muted-foreground border-border opacity-50"}`}>
                            <span>{meta.icon}</span>{meta.label}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      ) : (
        /* Notification Center */
        <div className="max-w-2xl">
          <div className="bg-card rounded-xl border border-border divide-y divide-border overflow-hidden">
            {feed.map(n => {
              const Icon = n.icon;
              return (
                <div key={n.id} onClick={() => setFeed(prev => prev.map(x => x.id === n.id ? { ...x, read: true } : x))}
                  className={`flex items-start gap-3 px-5 py-4 hover:bg-muted/30 cursor-pointer transition-colors ${!n.read ? "bg-accent/20" : ""}`}>
                  <div className={`w-9 h-9 rounded-full flex items-center justify-center flex-shrink-0 ${n.color}`}>
                    <Icon className="w-4 h-4" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-foreground">{n.title}</p>
                    <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">{n.body}</p>
                    <p className="text-[10px] text-muted-foreground mt-1.5">{n.time}</p>
                  </div>
                  {!n.read && <span className="w-2 h-2 rounded-full bg-primary flex-shrink-0 mt-1.5" />}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function AddDayChip({ onAdd }: { onAdd: (day: number) => void }) {
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState("");
  if (editing) return (
    <div className="flex items-center gap-1">
      <input type="number" value={val} onChange={e => setVal(e.target.value)} placeholder="days" autoFocus
        className="w-14 text-xs px-2 py-1 bg-card border border-border rounded-lg focus:outline-none focus:ring-1 focus:ring-ring/50"
        onKeyDown={e => { if (e.key === "Enter") { onAdd(+val); setVal(""); setEditing(false); } if (e.key === "Escape") setEditing(false); }} />
      <button onClick={() => { onAdd(+val); setVal(""); setEditing(false); }} className="text-primary hover:text-primary/80 text-xs font-bold">+</button>
    </div>
  );
  return (
    <button onClick={() => setEditing(true)} className="flex items-center gap-1 px-2 py-1 rounded-full border border-dashed border-border text-muted-foreground hover:border-primary hover:text-primary transition-colors text-xs">
      <Plus className="w-3 h-3" />Add
    </button>
  );
}

