/** Unwrap an API error into something readable: the server sends `{"error":"…"}` as the throw message. */
const errText = (e: any, fallback: string) => {
  const raw = String(e?.message ?? "").replace(/^\{"error":"|"\}$/g, "").trim();
  return raw && raw !== "undefined" ? raw : fallback;
};

